function FontFaces(): ReactNode {
  return <style>{FONT_CSS}</style>;
}

function factionRule(team?: Team | "gm"): string {
  if (team === "Unaligned") return C.silver;
  return C.gold;
}

function shellStyle(team: Team | "gm"): CSSProperties {
  let mist =
    "radial-gradient(ellipse at 50% -10%, rgba(201,168,90,0.10), transparent 55%)";
  if (team === "Lumen") {
    mist =
      "radial-gradient(ellipse at 20% 0%, rgba(94,122,82,0.32), transparent 58%), radial-gradient(ellipse at 90% 100%, rgba(232,207,138,0.16), transparent 52%)";
  } else if (team === "Ashen") {
    mist =
      "radial-gradient(ellipse at 18% 0%, rgba(158,27,27,0.42), transparent 58%), radial-gradient(ellipse at 88% 110%, rgba(210,55,43,0.18), transparent 50%)";
  } else if (team === "Unaligned") {
    mist =
      "radial-gradient(ellipse at 18% 0%, rgba(46,35,66,0.72), transparent 58%), radial-gradient(ellipse at 88% 110%, rgba(156,141,174,0.22), transparent 52%)";
  }
  return {
    minHeight: "100vh",
    backgroundColor: team === "Ashen" ? C.black : C.bg,
    backgroundImage: mist + ", url(\"" + GRAIN_URI + "\")",
    backgroundRepeat: "no-repeat, repeat",
    backgroundSize: "100% 100%, 96px 96px",
    color: C.text,
    fontFamily: FONT.body,
    boxSizing: "border-box",
  };
}

function RolePortrait(props: { roleId: string; kind: "hero" | "thumb" | "tiny"; name: string }): ReactNode {
  const src = PORTRAITS[props.roleId];
  const team = roleOf(props.roleId).team;
  const rule = factionRule(team);
  const wash =
    team === "Ashen" ? C.blood : team === "Unaligned" ? C.violet : C.sage;
  if (props.kind === "hero") {
    return (
      <div
        style={{
          width: "100%",
          aspectRatio: "3 / 4",
          overflow: "hidden",
          background: C.charcoal,
          borderBottom: "1px solid " + rule,
        }}
      >
        {src ? (
          <img src={src} alt={props.name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
        ) : (
          <div style={{ width: "100%", height: "100%", background: "linear-gradient(180deg, " + wash + " 0%, " + C.charcoal + " 100%)" }} />
        )}
      </div>
    );
  }
  const w = props.kind === "thumb" ? 48 : 28;
  const h = props.kind === "thumb" ? 64 : 37;
  const box: CSSProperties = {
    width: w,
    height: h,
    objectFit: "cover",
    display: "block",
    flex: "0 0 auto",
    border: "1px solid " + rule,
    background: src ? C.charcoal : "linear-gradient(180deg, " + wash + " 0%, " + C.charcoal + " 100%)",
  };
  if (src) return <img src={src} alt={props.name} style={box} />;
  return <div style={box} />;
}

const SYMBOLS: Record<Team, string> = {
  Lumen: "" +
    "data:image/webp;base64," +
    "",
  Ashen: "" +
    "data:image/webp;base64," +
    "",
  Unaligned: "" +
    "data:image/webp;base64," +
    "",
};

function FactionChip(props: { team: Team; size?: number }): ReactNode {
  const size = props.size && props.size > 0 ? props.size : 20;
  return (
    <img
      src={SYMBOLS[props.team]}
      alt={props.team}
      title={props.team}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        display: "inline-block",
        flex: "0 0 auto",
        marginRight: 6,
        verticalAlign: "middle",
        objectFit: "contain",
      }}
    />
  );
}

