function parseNeighborResult(text: string): { left: string; right: string; yes: boolean } | undefined {
  const m = text.match(/^Your neighbors \((.+) and (.+)\) (share alignment|do not share alignment)\./);
  if (!m) return undefined;
  return { left: m[1] as string, right: m[2] as string, yes: m[3] === "share alignment" };
}

function parseJudgeResult(text: string): string[] | undefined {
  const key = "These four players include exactly one Ashen: ";
  const i = text.indexOf(key);
  if (i < 0) return undefined;
  const rest = text.slice(i + key.length).split(".")[0] || "";
  const names = rest.split(",").map((n: string) => n.trim()).filter((n: string) => n !== "");
  return names.length ? names : undefined;
}

function parseWitnessResult(text: string): { kind: "role" | "none"; role?: string } | undefined {
  if (text.indexOf("Nobody was executed") >= 0 || text.indexOf("No one was executed") >= 0) return { kind: "none" };
  const m = text.match(/The player executed at the previous Dawn Accord was ([^.]+)\./);
  if (m) return { kind: "role", role: m[1] };
  return undefined;
}

function ResultMoments(props: { state: GameState; player: Player; results: ResultMsg[] }): ReactNode {
  if (props.results.length === 0 && props.player.roleId !== "the-quadrant-judge" && props.player.roleId !== "the-lumen-bearer") return null;
  const blocks: ReactNode[] = [];
  const allFor = props.state.results.filter((r: ResultMsg) => r.playerId === props.player.id);
  const judge = allFor.map((r: ResultMsg) => parseJudgeResult(r.text)).find((x: string[] | undefined) => x);
  const bearer = allFor.map((r: ResultMsg) => parseNeighborResult(r.text)).find((x: { left: string; right: string; yes: boolean } | undefined) => x);
  if (judge) {
    blocks.push(
      <div key="judge" style={{ marginBottom: 12 }}>
        <div style={{ fontFamily: FONT.label, color: C.gold, letterSpacing: "0.12em", fontSize: 11, textTransform: "uppercase", marginBottom: 8 }}>
          One of these four is Ashen.
          <PendingTag />
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          {judge.map((name: string, i: number) => (
            <div key={name + String(i)} style={{ padding: "12px 10px", border: "1px solid " + C.goldDim, background: C.black, textAlign: "center", fontFamily: FONT.title, letterSpacing: "0.06em", textTransform: "uppercase", color: C.parchment }}>
              {name}
            </div>
          ))}
        </div>
      </div>,
    );
  }
  if (bearer) {
    blocks.push(
      <div key="bearer" style={{ marginBottom: 12 }}>
        <div style={{ fontFamily: FONT.label, color: C.gold, letterSpacing: "0.12em", fontSize: 11, textTransform: "uppercase", marginBottom: 6 }}>
          Neighbors
          <PendingTag />
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10, flexWrap: "wrap" }}>
          <div style={{ padding: "8px 12px", border: "1px solid " + C.gold, color: C.parchment }}>{bearer.left}</div>
          <div
            style={{
              width: 22,
              height: 22,
              borderRadius: "50%",
              background: bearer.yes ? C.goldHi : C.ash,
              boxShadow: bearer.yes ? "0 0 14px " + C.gold : "none",
              border: "1px solid " + (bearer.yes ? C.gold : C.dead),
            }}
            title={bearer.yes ? "Yes" : "No"}
          />
          <div style={{ padding: "8px 12px", border: "1px solid " + C.gold, color: C.parchment }}>{bearer.right}</div>
        </div>
        <div style={{ textAlign: "center", marginTop: 8, color: bearer.yes ? C.goldHi : C.muted, fontFamily: FONT.body, fontSize: 16 }}>
          {bearer.yes ? "They share alignment." : "They do not share alignment."}
        </div>
      </div>,
    );
  }
  for (const r of props.results) {
    const snap = r.text.indexOf("Start-of-round snapshot") === 0;
    const wit = parseWitnessResult(r.text);
    const para = r.text.indexOf("Coin flip:") === 0 || r.text.indexOf("You survived an Ashen kill") === 0;
    const swap = r.text.indexOf("Your abilities have been swapped") === 0;
    const eyeHit = r.text.indexOf(" is the Ash Touched player.") >= 0;
    const eyeMiss = r.text.indexOf(" is not the Ash Touched player.") >= 0;
    const warden = r.text.indexOf("'s condition for the following day:") >= 0;
    const paraTeam = r.text.indexOf(" are on the same team.") >= 0 || r.text.indexOf(" are not on the same team.") >= 0;
    const shadow = r.text.indexOf(" is The Ashen Tyrant.") >= 0 || r.text.indexOf(" is not The Ashen Tyrant.") >= 0;
    if (judge && parseJudgeResult(r.text)) continue;
    if (bearer && parseNeighborResult(r.text)) continue;
    if (snap) {
      const body = r.text.replace(/^Start-of-round snapshot[^.]*\.\s*/, "");
      const rows = body.split("; ").filter((x: string) => x.trim() !== "");
      blocks.push(
        <div key={r.id} style={{ marginBottom: 12, padding: 12, border: "1px solid " + C.ember, background: "linear-gradient(180deg, #1a1010 0%, #0d0b0c 100%)" }}>
          <div style={{ fontFamily: FONT.label, color: C.ember, letterSpacing: "0.14em", fontSize: 11, textTransform: "uppercase", marginBottom: 8 }}>
            As of the start of Round {r.round || props.state.round}
            <PendingTag />
          </div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>Living players only. Masked roles appear as other Lumen roles.</div>
          {rows.map((line: string, i: number) => (
            <div key={i} style={{ padding: "6px 0", borderTop: "1px solid rgba(210,55,43,0.25)", color: C.parchment, fontSize: 16 }}>
              {line}
            </div>
          ))}
        </div>,
      );
      continue;
    }
    if (wit) {
      blocks.push(
        <div key={r.id} style={{ marginBottom: 12, padding: 16, border: "1px solid " + C.gold, background: C.black, textAlign: "center" }}>
          <div style={{ fontFamily: FONT.label, letterSpacing: "0.16em", fontSize: 11, textTransform: "uppercase", color: C.gold, marginBottom: 8 }}>
            Last Witness reveal
            <PendingTag />
          </div>
          {wit.kind === "none" ? (
            <div style={{ color: C.muted, fontSize: 16 }}>No one was executed. The Witness sees nothing tonight.</div>
          ) : (
            <div>
              {props.state.lastExecutedName ? <div style={{ color: C.muted, fontSize: 14, marginBottom: 6 }}>{props.state.lastExecutedName}</div> : null}
              <div style={{ fontFamily: FONT.title, fontSize: 22, letterSpacing: "0.08em", textTransform: "uppercase", color: C.goldHi }}>{wit.role}</div>
            </div>
          )}
        </div>,
      );
      continue;
    }
    if (para) {
      const tails = r.text.indexOf("Tails") >= 0 || r.text.indexOf("now Ashen") >= 0;
      const heads = r.text.indexOf("Heads") >= 0 || r.text.indexOf("remain Lumen") >= 0;
      blocks.push(
        <div
          key={r.id}
          style={{
            marginBottom: 12,
            padding: 16,
            border: "1px solid " + (tails ? C.ember : C.gold),
            background: tails ? "linear-gradient(180deg, #3a1a12 0%, #0E0C10 100%)" : "linear-gradient(180deg, #2a2414 0%, #0E0C10 100%)",
            textAlign: "center",
          }}
        >
          <div style={{ fontFamily: FONT.label, letterSpacing: "0.16em", fontSize: 11, textTransform: "uppercase", color: tails ? C.ember : C.goldHi, marginBottom: 8 }}>
            Coin flip
            <PendingTag />
          </div>
          <div
            style={{
              width: 56,
              height: 56,
              borderRadius: "50%",
              margin: "0 auto 10px",
              border: "2px solid " + (tails ? C.ember : C.goldHi),
              background: tails ? C.blood : C.gold,
              color: tails ? C.parchment : C.ink,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: FONT.title,
              fontSize: 18,
            }}
          >
            {tails ? "T" : heads ? "H" : "•"}
          </div>
          <div style={{ color: C.parchment, fontSize: 16, lineHeight: 1.5 }}>{r.text}</div>
        </div>,
      );
      continue;
    }
    if (warden) {
      const label = (r.text.split(": ")[1] || "").replace(/\.$/, "");
      const chips = [
        { id: "ash", text: "Ash Touched", on: label === "Ash Touched" },
        { id: "mire", text: "Mire Touched", on: label.indexOf("Mire Touched") >= 0 && label.indexOf("both") < 0 },
        { id: "both", text: "Both", on: label.indexOf("both") >= 0 },
        { id: "neither", text: "Neither", on: label === "neither" },
      ];
      blocks.push(
        <div key={r.id} style={{ marginBottom: 12 }}>
          <div style={{ marginBottom: 6, color: C.text, fontSize: 15 }}>{r.text}</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {chips.map((c: { id: string; text: string; on: boolean }) => (
              <span
                key={c.id}
                style={{
                  padding: "4px 8px",
                  border: "1px solid " + (c.on ? C.goldHi : C.goldDim),
                  color: c.on ? C.ink : C.muted,
                  background: c.on ? C.gold : "transparent",
                  fontFamily: FONT.label,
                  fontSize: 10,
                  letterSpacing: "0.08em",
                  textTransform: "uppercase",
                }}
              >
                {c.text}
              </span>
            ))}
            <PendingTag />
          </div>
        </div>,
      );
      continue;
    }
    if (paraTeam) {
      const yes = r.text.indexOf(" are on the same team.") >= 0;
      blocks.push(
        <div key={r.id} style={{ marginBottom: 12 }}>
          <div style={{ color: C.text, fontSize: 15, marginBottom: 8 }}>{r.text}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 0 }}>
            <div style={{ flex: 1, height: 8, background: C.goldDim, borderRadius: 2 }} />
            <div style={{ width: 40, height: 4, background: yes ? C.goldHi : "transparent", borderTop: yes ? "none" : "2px dashed " + C.ember }} />
            <div style={{ flex: 1, height: 8, background: C.goldDim, borderRadius: 2 }} />
            <PendingTag />
          </div>
        </div>,
      );
      continue;
    }
    if (eyeHit || eyeMiss) {
      blocks.push(
        <div key={r.id} style={{ marginBottom: 12, padding: 12, border: "1px solid " + (eyeHit ? C.ember : C.ash), textAlign: "center" }}>
          <div
            style={{
              width: 36,
              height: 22,
              margin: "0 auto 8px",
              border: "2px solid " + (eyeHit ? C.ember : C.muted),
              borderRadius: eyeMiss ? 2 : "50%",
              background: eyeHit ? C.ember : C.black,
              opacity: eyeMiss ? 0.45 : 1,
            }}
          />
          <div style={{ color: eyeHit ? C.ember : C.muted, fontSize: 16 }}>{r.text}</div>
          <PendingTag />
        </div>,
      );
      continue;
    }
    if (shadow) {
      const yes = r.text.indexOf(" is The Ashen Tyrant.") >= 0;
      blocks.push(
        <div key={r.id} style={{ marginBottom: 12, padding: 12, border: "1px solid " + (yes ? C.ember : C.silver) }}>
          <div style={{ color: yes ? C.ember : C.parchment, fontSize: 16 }}>{r.text}</div>
        </div>,
      );
      continue;
    }
    if (swap) {
      blocks.push(
        <div key={r.id} style={{ marginBottom: 8, color: C.ember, fontSize: 15, lineHeight: 1.45 }}>
          {r.text}
        </div>,
      );
      continue;
    }
    blocks.push(
      <div key={r.id} style={{ marginBottom: 8, fontSize: 14, lineHeight: 1.45 }}>
        <span style={{ color: C.goldDim }}>Round {r.round || "setup"} · </span>
        {r.text}
      </div>,
    );
  }
  if (blocks.length === 0) return null;
  return <SectionCard title="Results / Messages">{blocks}</SectionCard>;
}

function phaseCard(state: GameState): ReactNode {
  return (
    <SectionCard title="Phase">
      <div style={{ fontSize: 18, color: C.gold }}>{phaseLabel(state.phase)}{state.round ? " · Round " + state.round : ""}</div>
      {state.publicNotices.map((n: string, i: number) => (
        <div key={i} style={{ marginTop: 6, color: n.indexOf("Last vision") >= 0 ? C.goldHi : C.text, fontSize: 14 }}>
          {n}
          {n.indexOf("Last vision") >= 0 ? <PendingTag /> : null}
        </div>
      ))}
    </SectionCard>
  );
}

function notesCard(props: PlayerViewProps, p: Player): ReactNode {
  return (
    <SectionCard title="Notes">
      <textarea
        style={{ ...inputStyle(), minHeight: 120, resize: "vertical" }}
        value={p.notes}
        placeholder="Private notes — only you can see these."
        onChange={(e: ChangeEvent<HTMLTextAreaElement>) => props.patchNotes(e.target.value)}
      />
    </SectionCard>
  );
}

function gmChatCard(props: PlayerViewProps, p: Player): ReactNode {
  const gmMsgs = props.state.chats.filter((m: ChatMsg) => m.channel === "gm:" + p.id);
  return (
    <SectionCard title="Private chat with the GM">
      <ChatPane
        fontFamily=""
        messages={gmMsgs}
        draft={props.drafts["gm:" + p.id] || ""}
        onDraft={(v: string) => props.setDraft("gm:" + p.id, v)}
        onSend={() => props.sendChat("gm:" + p.id, p.id)}
        placeholder="Message the GM…"
        nameOf={props.nameOf}
      />
    </SectionCard>
  );
}

function ashenChatCard(props: PlayerViewProps, p: Player, pending?: boolean): ReactNode {
  const ashenMsgs = props.state.chats.filter((m: ChatMsg) => m.channel === "ashen");
  return (
    <SectionCard title="Ashen team chat" note={pending ? undefined : undefined}>
      {pending ? (
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
          Dead Ashen still see this chat in this prototype.
          <PendingTag />
        </div>
      ) : null}
      <ChatPane
        fontFamily=""
        messages={ashenMsgs}
        draft={props.drafts.ashen || ""}
        onDraft={(v: string) => props.setDraft("ashen", v)}
        onSend={() => props.sendChat("ashen", p.id)}
        placeholder="Message the Ashen…"
        nameOf={props.nameOf}
      />
    </SectionCard>
  );
}

function remnantView(props: PlayerViewProps): ReactNode {
  const p = props.player;
  const state = props.state;
  const summoned = state.summonedIds.indexOf(p.id) >= 0 && state.phase === "dawnAccord";
  const lastShotReady =
    p.roleId === "sunmark-shooter" &&
    p.charges > 0 &&
    state.phase === "dawnAccord" &&
    state.hadExecution &&
    state.lastExecutedRoleId === "sunmark-shooter" &&
    state.lastExecutedName === p.name;
  const living = livingPlayers(state.players);
  const others = living.filter((x: Player) => x.id !== p.id);
  const necro = state.players.find((x: Player) => x.roleId === "the-necroreclaimer");
  const necroVote = necro ? state.votes[necro.id] || "" : "";
  return (
    <div style={{ filter: "grayscale(0.35) saturate(0.75)" }}>
      <SectionCard title="Remnant of the Vanished" note="Your role card stays private. You may not reveal your role. You may still make public statements and help your team.">
        <div style={{ color: C.muted, fontSize: 15, marginBottom: 8 }}>No abilities. Action boards are closed.</div>
        <div style={{ fontFamily: FONT.label, letterSpacing: "0.1em", textTransform: "uppercase", color: p.finalVoteAvailable ? C.goldHi : C.muted, fontSize: 12 }}>
          Final vote: {p.finalVoteAvailable ? "available" : "used"}
        </div>
      </SectionCard>
      <RoleCardBlock state={state} player={p} />
      {phaseCard(state)}
      {tableCard(state)}
      {lastShotReady ? (
        <SectionCard title="Last shot" note="You were executed while still holding a shot. Fire one last shot before you leave. It follows the same hit rules and is resolved publicly.">
          <SelectList label="Target" value={props.pickA} onChange={props.setPickA} options={others.map((x: Player) => ({ value: x.id, label: x.name }))} />
          <div style={{ marginTop: 10 }}>
            <button
              type="button"
              style={btnStyle("gold")}
              disabled={props.pickA === "" || actionFor(state, p.id, "dawnAccord") !== undefined}
              onClick={() => props.submitAction(p, "Sunmark last shot", [props.pickA], false, "", "dawnAccord", true)}
            >
              Fire last shot
            </button>
          </div>
          {actionFor(state, p.id, "dawnAccord") ? <div style={{ marginTop: 8, color: C.success, fontSize: 13 }}>Last shot submitted.</div> : null}
        </SectionCard>
      ) : null}
      {summoned ? (
        <SectionCard title="Summoned" note="You have been summoned by The Necroreclaimer. You must answer its first yes-or-no question truthfully; after that you may lie. Your ballot is locked to its vote.">
          <div style={{ color: C.goldHi, marginBottom: 8, fontSize: 15 }}>
            Locked ballot: {necroVote ? "mirrors " + (necro ? necro.name : "The Necroreclaimer") + " — " + props.nameOf(necroVote) : "waiting for The Necroreclaimer to vote."}
          </div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
            This summoned vote does not spend your final vote in this prototype.
            <PendingTag />
          </div>
          <ChatPane
            fontFamily=""
            messages={state.chats.filter((m: ChatMsg) => m.channel === summonChannel(state.round))}
            draft={props.drafts[summonChannel(state.round)] || ""}
            onDraft={(v: string) => props.setDraft(summonChannel(state.round), v)}
            onSend={() => props.sendChat(summonChannel(state.round), p.id)}
            placeholder="Answer the Necroreclaimer (yes or no)…"
            nameOf={props.nameOf}
          />
        </SectionCard>
      ) : null}
      {state.phase === "dawnAccord" && p.finalVoteAvailable && !summoned ? (
        <SectionCard title="The Dawn Accord" note="Caden: dead players keep one final Dawn Accord vote and cannot reveal their role. Only the first 3 dead votes count each Accord (Caden, Nov 18). Table practice: that vote is single-use for the rest of the game and may be saved for a later Accord; dead players do not nominate. Design default D53 (Nov 21 audit): a rejected dead vote is saved, a dead Voice counts as 1, and a player summoned by The Necroreclaimer can't also cast a personal final vote that Accord.">
          <PracticeTag />
          <PendingTag />
          <FinalVoteForm state={state} player={p} />
        </SectionCard>
      ) : null}
      {p.team === "Ashen" ? ashenChatCard(props, p, true) : null}
      {gmChatCard(props, p)}
      {notesCard(props, p)}
      {endRolesCard(state)}
      {state.dealt ? allRolesCard() : null}
    </div>
  );
}

function FinalVoteForm(props: { state: GameState; player: Player }): ReactNode {
  const nominees = props.state.nominees.filter((id: string) => id !== "");
  const current = props.state.votes[props.player.id] || "";
  const [choice, setChoice] = useState(current);
  const [, setTick] = useState(0);
  if (nominees.length === 0) {
    return <div style={{ color: C.muted }}>The ballot is not posted yet.</div>;
  }
  // Caden (Nov 18 card): dead votes are final.
  if (current !== "" && current !== "SAVE") {
    return (
      <div style={{ color: C.success, fontSize: 15 }}>
        You voted for {nameOfFrom(props.state, current)}. Dead votes are final, so it can't be changed.
      </div>
    );
  }
  // Caden (Nov 18): only the first 3 dead votes count each Accord.
  if (deadVoteBlocked(props.state, props.player)) {
    return (
      <div style={{ color: C.ember, fontSize: 15 }}>
        Max votes reached. Three dead votes have already been cast this Accord, so you can't vote now. You keep your final vote for a later Accord.
      </div>
    );
  }
  return (
    <div>
      <SelectList
        label="Execute, or Save"
        value={choice}
        onChange={setChoice}
        options={nominees
          .map((id: string) => ({ value: id, label: nameOfFrom(props.state, id) }))
          .concat([{ value: "SAVE", label: "Save (keep this vote for later)" }])}
      />
      <div style={{ marginTop: 10 }}>
        <CastVote
          playerId={props.player.id}
          choice={choice}
          weightHint={1}
          onCast={() => setTick((n: number) => n + 1)}
        />
      </div>
      {choice !== "SAVE" && choice !== "" ? (
        <div style={{ marginTop: 8, color: C.ember, fontSize: 14 }}>This is your only one.</div>
      ) : null}
      {current ? (
        <div style={{ marginTop: 8, color: C.success, fontSize: 13 }}>
          {current === "SAVE" ? "You are saving your final vote." : "You have voted for " + nameOfFrom(props.state, current) + "."}
        </div>
      ) : null}
    </div>
  );
}

function syndicRoster(_state: GameState): ReactNode {
  return (
    <div style={{ marginBottom: 10 }}>
      <div style={{ fontFamily: FONT.label, fontSize: 11, letterSpacing: "0.12em", textTransform: "uppercase", color: C.lavender, marginBottom: 6 }}>
        Guild
        <PendingTag />
      </div>
      <div style={{ color: C.muted, fontSize: 14 }}>Membership stays private to the GM unless revealed. This prototype does not show you who accepted.</div>
    </div>
  );
}

function playerView(props: PlayerViewProps): ReactNode {
  const p = props.player;
  const state = props.state;
  if (!p.alive) return remnantView(props);
  const role = roleOf(p.roleId);
  const isAshen = p.team === "Ashen";
  const teammates = state.players.filter((x: Player) => x.team === "Ashen" && x.id !== p.id);
  const results = state.results.filter((r: ResultMsg) => r.playerId === p.id);
  const living = livingPlayers(state.players);
  const dead = state.players.filter((x: Player) => !x.alive);
  const kind = ashKindFor(state, p);
  const echoKind = echoAshKind(state, p);
  const inherit = hasInheritedKill(state, p);
  const nightKind = kind !== "none" ? kind : echoKind;
  const others = living.filter((x: Player) => x.id !== p.id);
  const nonAshen = living.filter((x: Player) => x.team !== "Ashen" && x.id !== p.id);
  const opt = (list: Player[]) => list.map((x: Player) => ({ value: x.id, label: x.name }));
  const pendingInvite = results.some((r: ResultMsg) => r.text.indexOf("invited you to join the syndicate") >= 0) && !p.syndicateMember;
  const submittedNight = actionFor(state, p.id, "ashFall");
  const submittedDay = actionFor(state, p.id, "lumination");
  const canAct = state.winner === "" && p.alive && state.dealt;
  const bladeDrawn = p.roleId === "the-shadow-blade" && state.shadowTakeover && p.id === state.successorId;

  return (
    <div>
      <RoleCardBlock state={state} player={p} />
      {phaseCard(state)}
      {tableCard(state)}
      {isAshen ? (
        <SectionCard title="Ashen teammates" note="Names only — their roles are not shown. It is your team's work to learn them.">
          <div style={{ fontSize: 16, display: "flex", alignItems: "center", gap: 8 }}>
            <FactionChip team="Ashen" size={22} />
            <span>{teammates.length ? teammates.map((x: Player) => x.name).join(", ") : "You are the only Ashen in play."}</span>
          </div>
        </SectionCard>
      ) : null}

      {bladeDrawn ? (
        <SectionCard title="The blade is drawn">
          <div style={{ color: C.lavender, fontSize: 16, fontStyle: "italic" }}>The blade is drawn.</div>
          {inheritedKillPaused(state) ? (
            <div style={{ marginTop: 6, color: C.goldHi, fontSize: 16 }}>
              {state.phase === "ashFall" && state.round === state.peaceRound ? "Tonight is a night of peace." : "A night of peace comes first: no kill on Ash Fall " + state.peaceRound + "."} Your kill begins on Ash Fall {(state.peaceRound || 0) + 1}.
            </div>
          ) : null}
          <PendingTag />
        </SectionCard>
      ) : null}

      {state.tyrantHasDied && !state.shadowTakeover && p.alive && p.id === state.successorId && state.winner === "" ? (
        <SectionCard title="Inherited Tyrant kill">
          <div style={{ color: C.goldHi, fontSize: 16 }}>
            {inheritedKillPaused(state)
              ? (state.phase === "ashFall" && state.round === state.peaceRound ? "Tonight is a night of peace: no inherited kill." : "A night of peace comes first: no inherited kill on Ash Fall " + state.peaceRound + ".") +
                " You first kill on Ash Fall " +
                ((state.peaceRound || 0) + 1) +
                "."
              : "You hold the inherited Tyrant kill. Use it each Ash Fall."}
          </div>
        </SectionCard>
      ) : null}

      {p.roleId === "the-syndic" ? (
        <SectionCard title="The Syndic">
          {syndicRoster(state)}
        </SectionCard>
      ) : null}

      {ResultMoments({ state: state, player: p, results: results })}

      {role.id === "the-vitality-overseer" && submittedNight && submittedNight.targets[0] ? (
        <div style={{ marginBottom: 16, color: C.lumen, fontSize: 14 }}>
          A soft glow marks {props.nameOf(submittedNight.targets[0] as string)} until the end of Lumination.
          <PendingTag />
        </div>
      ) : null}
      {role.id === "the-failsafe" && submittedNight && submittedNight.targets[0] ? (
        <div style={{ marginBottom: 16, color: C.gold, fontSize: 14 }}>
          Seal set on {props.nameOf(submittedNight.targets[0] as string)}.
          <PendingTag />
        </div>
      ) : null}
      {role.id === "the-silent-hand" && submittedNight && submittedNight.targets[0] ? (
        <div style={{ marginBottom: 16, color: C.muted, fontSize: 14 }}>
          You muted {props.nameOf(submittedNight.targets[0] as string)}. They are not told. This prototype does not tell you whether the cancel impacted the vote.
          <PendingTag />
        </div>
      ) : null}

      {canAct && state.phase === "ashFall" ? (
        <SectionCard title="Ash Fall action">
          {nightActionForm(props, nightKind, inherit, opt(living), opt(others), opt(nonAshen), submittedNight)}
        </SectionCard>
      ) : null}

      {canAct && state.phase === "ashFall" && p.syndShield ? (
        <SectionCard title="Syndicate shield" note="One time only. Use it before you know whether you would die tonight. It protects you for this Ash Fall and the following Lumination.">
          <div style={wrap}>
            <button type="button" style={btnStyle(p.syndShieldArmed ? "gold" : "quiet")} onClick={() => props.armSyndShield && props.armSyndShield(p, !p.syndShieldArmed)}>
              {p.syndShieldArmed ? "Shield set for tonight (tap to withdraw)" : "Use my shield tonight"}
            </button>
            <PendingTag />
          </div>
        </SectionCard>
      ) : null}

      {canAct && state.phase === "lumination" ? (
        <SectionCard title="Lumination action">{dayActionForm(props, submittedDay, opt(others), opt(dead))}</SectionCard>
      ) : null}

      {canAct && state.phase === "lumination" ? (
        <SectionCard title="Nomination" note="Each living player makes one nomination. The Voice of the Accord's nomination counts as 2. Dead players do not nominate.">
          <PracticeTag />
          <NominationForm state={state} player={p} living={living} nominatePlayer={props.nominatePlayer} />
        </SectionCard>
      ) : null}

      {canAct && state.phase === "lumination" && p.roleId === "the-necroreclaimer" && state.summonedIds.length === 2 ? (
        <SectionCard title="Summon chat" note="Yes-or-no questions only. Each summoned player must answer its first question truthfully. The GM can watch.">
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
            First answer is binding.
            <PendingTag />
          </div>
          <ChatPane
            fontFamily=""
            messages={state.chats.filter((m: ChatMsg) => m.channel === summonChannel(state.round))}
            draft={props.drafts[summonChannel(state.round)] || ""}
            onDraft={(v: string) => props.setDraft(summonChannel(state.round), v)}
            onSend={() => props.sendChat(summonChannel(state.round), p.id)}
            placeholder="Ask a yes-or-no question…"
            nameOf={props.nameOf}
          />
        </SectionCard>
      ) : null}

      {canAct && state.phase === "dawnAccord" ? (
        <SectionCard title="The Dawn Accord" note="Vote for one name on the ballot. Most votes wins; a tie means no execution. The Voice of the Accord's vote counts as 2.">
          <div style={{ marginBottom: 8 }}>
            <PracticeTag />
          </div>
          <VoteForm state={state} player={p} />
        </SectionCard>
      ) : null}

      {pendingInvite && p.alive ? (
        <SectionCard title="Syndicate invite">
          <div style={wrap}>
            <button type="button" style={btnStyle("gold")} onClick={() => props.answerInvite(p, true)}>
              Accept
            </button>
            <button type="button" style={btnStyle("quiet")} onClick={() => props.answerInvite(p, false)}>
              Decline
            </button>
          </div>
        </SectionCard>
      ) : null}

      {endRolesCard(state)}
      {state.dealt ? allRolesCard() : (
        <SectionCard title="Waiting">
          <div style={{ color: C.muted }}>The GM has not dealt roles yet. You will see your role card and the public list here after the deal.</div>
        </SectionCard>
      )}

      {gmChatCard(props, p)}

      {isAshen ? ashenChatCard(props, p, false) : null}

      {notesCard(props, p)}
    </div>
  );
}

function nightActionForm(
  props: PlayerViewProps,
  kind: AshKind,
  inherit: boolean,
  living: { value: string; label: string }[],
  others: { value: string; label: string }[],
  nonAshen: { value: string; label: string }[],
  submitted: ActionSub | undefined,
): ReactNode {
  const p = props.player;
  const canSubmit = (targets: string[], skip: boolean, needs: number) => {
    if (skip) return true;
    if (targets.length < needs) return false;
    if (needs === 2 && targets[0] === targets[1]) return false;
    return true;
  };
  const blocks: ReactNode[] = [];
  if (kind === "none" && !inherit) {
    const eyeDone = effectiveRoleId(p) === "the-watching-eye" ? eyeDoneReason(props.state, p) : "";
    blocks.push(
      <div key="none" style={{ color: C.muted }}>
        {eyeDone !== ""
          ? "No Ash Fall action. " + eyeDone
          : "No Ash Fall action" + (props.state.echoCopyRoleId !== "" && p.roleId === "the-echo-thief" ? " — your copied ability has no night choice tonight." : ".")}
      </div>,
    );
  }
  const killForm = (label: string, note: string, confirm: boolean) => (
    <div>
      {note ? <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>{note}</div> : null}
      <label style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8, color: C.text }}>
        <input type="checkbox" checked={props.skipKill} onChange={(e: ChangeEvent<HTMLInputElement>) => props.setSkipKill(e.target.checked)} />
        Skip the kill
      </label>
      {props.skipKill ? null : <SelectList label="Target" value={props.pickA} onChange={props.setPickA} options={others} />}
      <div style={{ marginTop: 10 }}>
        <button
          type="button"
          style={btnStyle("gold")}
          disabled={!canSubmit(props.skipKill ? [] : [props.pickA], props.skipKill, 1)}
          onClick={() => props.submitAction(p, label, props.skipKill ? [] : [props.pickA], props.skipKill, "", "ashFall", false)}
        >
          {confirm ? "Confirm mark — final, no retry tonight" : "Submit"}
        </button>
      </div>
    </div>
  );
  if (kind === "killOrSkip" || kind === "paradoxKill" || kind === "shadowKill") {
    const label =
      kind === "shadowKill"
        ? "Shadow Blade kill"
        : kind === "paradoxKill"
          ? "Luminary Paradox kill"
          : "Ashen Tyrant kill";
    const note =
      kind === "paradoxKill"
        ? "Caden (Nov 18): your own kill every Ash Fall, separate from The Ashen Tyrant's kill (it is not the Tyrant kill and you never inherit that). Target rules are not spelled out; this prototype uses the Tyrant's kill rules (any other living player, or skip). Caden (Nov 18 card): it keeps its kill after the Tyrant dies; a night of peace does not pause it (Caden, Nov 18 card: \"Yes, the Paradox still kills\")."
        : kind === "shadowKill"
          ? "Your pre-takeover check is gone. Choose one other living player to kill, or skip. Self is not allowed. A blocked kill is used up with no retry and no explanation."
          : "Choose your mark: any other living player, including Ashen teammates, or skip. Self is not allowed. A blocked kill is used up with no retry and no explanation.";
    blocks.push(
      <div key="kill">
        {kind === "killOrSkip" ? <PendingTag /> : null}
        {killForm(label, note, kind === "killOrSkip")}
      </div>,
    );
  }
  if (kind === "poisonNonAshen") {
    blocks.push(
      <div key="poison">
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>Poison one non-Ashen living player, or skip. You cannot target yourself or Ashen teammates.</div>
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>This prototype does not show you poison counts or whether a poison landed. <PendingTag /></div>
        <label style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8, color: C.text }}>
          <input type="checkbox" checked={props.skipKill} onChange={(e: ChangeEvent<HTMLInputElement>) => props.setSkipKill(e.target.checked)} />
          Skip the poison
        </label>
        {props.skipKill ? null : <SelectList label="Target" value={props.pickA} onChange={props.setPickA} options={nonAshen} />}
        <div style={{ marginTop: 10 }}>
          <button
            type="button"
            style={btnStyle("gold")}
            disabled={!canSubmit(props.skipKill ? [] : [props.pickA], props.skipKill, 1)}
            onClick={() => props.submitAction(p, "Mirebane poison", props.skipKill ? [] : [props.pickA], props.skipKill, "", "ashFall", false)}
          >
            Submit
          </button>
        </div>
      </div>,
    );
  }
  if (kind === "shieldAny") {
    blocks.push(
      <div key="shield">
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
          Shield 1 player. You may shield yourself, and you may shield the same player on consecutive nights. Skipping isn't settled; this prototype requires a target.
          <PendingTag />
        </div>
        <SelectList label="Shield" value={props.pickA} onChange={props.setPickA} options={living} />
        <div style={{ marginTop: 10 }}>
          <button type="button" style={btnStyle("gold")} disabled={!canSubmit([props.pickA], false, 1)} onClick={() => props.submitAction(p, "Vitality Overseer shield", [props.pickA], false, "", "ashFall", false)}>
            Submit
          </button>
        </div>
      </div>,
    );
  }
  if (kind === "checkAny" || kind === "checkOther" || kind === "watchingEye" || kind === "shadowCheck" || kind === "cancelOther" || kind === "silenceOther") {
    const label =
      kind === "checkAny"
        ? "Foresight Elder check"
        : kind === "checkOther"
          ? "Integrity Warden check"
          : kind === "watchingEye"
            ? "Watching Eye check"
            : kind === "shadowCheck"
              ? "Shadow Blade check"
              : kind === "cancelOther"
                ? "Failsafe cancel"
                : "Silent Hand";
    const options = kind === "checkAny" || kind === "watchingEye" ? living : others;
    const note =
      kind === "watchingEye"
        ? "Ask whether one player is the Ash Touched player. You may check yourself. A hit tells you who The Ashen Tyrant is (never any other killer), and then you have no further checks; you also stop once the Tyrant is dead. If your target is Mire Touched, they are cured and you learn nothing. A miss poisons a random player other than you, and you are not told who. Once the Ash Touched player is dead, each check asks whether your target is The Ashen Tyrant instead, and a miss poisons nobody (Design defaults D43, D45, Nov 21 audit; the GM can switch them off at setup)."
        : kind === "shadowCheck"
          ? "Each Ash Fall, before you inherit the kill, choose one other living player. Learn whether they are The Ashen Tyrant."
          : kind === "cancelOther"
            ? "Choose 1 other player. Self is not allowed. You may repeat the same player on a later night. This prototype requires a target (skipping isn't settled) and gives you no feedback that the cancel landed."
            : kind === "checkAny"
              ? "Check 1 player. You may check yourself, and rechecks are allowed. Skipping isn't settled; this prototype requires a target. The result is Lumen or Ashen; Unaligned appear as Ashen. If you die tonight, a last vision of this check is shown to the whole table at dawn."
              : kind === "checkOther"
                ? "Choose 1 other player. Self is not allowed. Repeat targets and skipping aren't settled; this prototype requires a new target each night you act."
                : "Choose 1 other player. Self is not allowed. The cancel is silent — the target is not told. Repeat targets and skipping aren't settled; this prototype requires a target.";
    blocks.push(
      <div key={kind}>
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>{note}</div>
        {kind !== "shadowCheck" ? <PendingTag /> : null}
        <SelectList label="Target" value={props.pickA} onChange={props.setPickA} options={options} />
        <div style={{ marginTop: 10 }}>
          <button type="button" style={btnStyle("gold")} disabled={!canSubmit([props.pickA], false, 1)} onClick={() => props.submitAction(p, label, [props.pickA], false, "", "ashFall", false)}>
            Submit
          </button>
        </div>
      </div>,
    );
  }
  if (kind === "twoAny" || kind === "twoOther") {
    const options = kind === "twoOther" ? others : living;
    blocks.push(
      <div key="two">
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
          {kind === "twoAny"
            ? "Pick two different players. You may include yourself as one of the two."
            : "Pick two other players to swap. Self is not allowed. Repeat targets and skipping aren't settled; this prototype requires two targets. You get no feedback that the swap landed."}
        </div>
        {kind === "twoOther" ? <PendingTag /> : null}
        <div style={wrap}>
          <SelectList label="First player" value={props.pickA} onChange={props.setPickA} options={options} />
          <SelectList label="Second player" value={props.pickB} onChange={props.setPickB} options={options} />
        </div>
        <div style={{ marginTop: 10 }}>
          <button
            type="button"
            style={btnStyle("gold")}
            disabled={!canSubmit([props.pickA, props.pickB], false, 2)}
            onClick={() =>
              props.submitAction(
                p,
                kind === "twoAny" ? "Parallax check" : "Lucid Catalyst swap",
                [props.pickA, props.pickB],
                false,
                "",
                "ashFall",
                false,
              )
            }
          >
            Submit
          </button>
        </div>
      </div>,
    );
  }
  if (inherit && kind !== "killOrSkip") {
    blocks.push(
      <div key="inherit" style={{ marginTop: 12, borderTop: "1px solid " + C.border, paddingTop: 12 }}>
        {killForm("Inherited Tyrant kill", "You have inherited the Tyrant kill. Copying and inheriting do not stack if you also copied a Tyrant kill — submit only this kill. Paused during a night of peace (that control will not appear then).", false)}
      </div>,
    );
  }
  if (submitted) {
    blocks.push(
      <div key="sub" style={{ marginTop: 10, color: C.success, fontSize: 13 }}>
        Submitted: {submitted.label}
        {submitted.skip ? " (skip)" : submitted.targets.length ? " — " + submitted.targets.map((id: string) => props.nameOf(id)).join(", ") : ""}. You can submit again to replace it before the GM advances the phase.
      </div>,
    );
  }
  return <div>{blocks}</div>;
}

function dayActionForm(
  props: PlayerViewProps,
  submitted: ActionSub | undefined,
  others: { value: string; label: string }[],
  dead: { value: string; label: string }[],
): ReactNode {
  const p = props.player;
  const rid = effectiveRoleId(p);
  const day = roleOf(rid).day;
  const copiedDay = p.roleId === "the-echo-thief" && props.state.echoCopyRoleId !== "" ? roleOf(props.state.echoCopyRoleId).day : "none";
  const useDay: DayKind = day !== "none" ? day : copiedDay;
  if (useDay === "none") {
    return <div style={{ color: C.muted }}>No Lumination action for your role. You may still talk at the table and use your notes and chats.</div>;
  }
  const charged = useDay === "question" || useDay === "shot" || useDay === "summon" || useDay === "dayKill";
  if (charged && p.charges <= 0) {
    const left = deathsUntilRecharge(props.state, p);
    return (
      <div style={{ color: C.muted }}>
        No use remaining.
        {left !== undefined ? " You regain 1 use after " + left + " more death" + (left === 1 ? "" : "s") + " (Caden's 5-player rule)." : ""}
        <ChargePip held={false} usedAt={p.usedAtDeaths} deaths={props.state.deathCount || 0} />
      </div>
    );
  }
  return (
    <div>
      {useDay === "question" ? (
        <div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
            Whisper one question about one specific player and one specific role, for example "Is Caden The Ashen Child?" Optional — you may skip. This prototype allows a question about yourself, and the GM answers during this Lumination.
            <PendingTag />
          </div>
          <ChargePip held={p.charges > 0} usedAt={p.usedAtDeaths} deaths={props.state.deathCount || 0} />
          <label style={{ display: "flex", gap: 8, alignItems: "center", margin: "8px 0", color: C.text }}>
            <input type="checkbox" checked={props.skipKill} onChange={(e: ChangeEvent<HTMLInputElement>) => props.setSkipKill(e.target.checked)} />
            Skip this Lumination (keep the use)
          </label>
          {props.skipKill ? (
            <div style={{ marginTop: 10 }}>
              <button type="button" style={btnStyle("quiet")} onClick={() => props.submitAction(p, "Self Known question", [], true, "", "lumination", false)}>
                Hold the use
              </button>
            </div>
          ) : (
            <div>
              <div style={wrap}>
                <SelectList label="Player" value={props.pickA} onChange={props.setPickA} options={others.concat([{ value: p.id, label: p.name + " (you)" }])} />
                <SelectList label="Role" value={props.qRole} onChange={props.setQRole} options={ROLES.map((r: RoleDef) => ({ value: r.id, label: r.name }))} />
              </div>
              <div style={{ marginTop: 10 }}>
                <button
                  type="button"
                  style={btnStyle("gold")}
                  disabled={props.pickA === "" || props.qRole === ""}
                  onClick={() => {
                    const name = props.nameOf(props.pickA);
                    const roleName = roleOf(props.qRole).name;
                    props.submitAction(p, "Self Known question", [props.pickA], false, "Is " + name + " " + roleName + "?", "lumination", true);
                  }}
                >
                  Submit question
                </button>
              </div>
            </div>
          )}
        </div>
      ) : null}
      {useDay === "shot" ? (
        <div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
            Publicly declare a shot at one other player, or don't shoot. Max 1 per Lumination if a shot is held. Self-target isn't settled; this prototype does not offer it.
            <PendingTag />
          </div>
          <ChargePip held={p.charges > 0} usedAt={p.usedAtDeaths} deaths={props.state.deathCount || 0} />
          <label style={{ display: "flex", gap: 8, alignItems: "center", margin: "8px 0", color: C.text }}>
            <input type="checkbox" checked={props.skipKill} onChange={(e: ChangeEvent<HTMLInputElement>) => props.setSkipKill(e.target.checked)} />
            Don't shoot (keep the shot)
          </label>
          {props.skipKill ? (
            <div style={{ marginTop: 10 }}>
              <button type="button" style={btnStyle("quiet")} onClick={() => props.submitAction(p, "Sunmark shot", [], true, "", "lumination", false)}>
                Hold the shot
              </button>
            </div>
          ) : (
            <div>
              <SelectList label="Target" value={props.pickA} onChange={props.setPickA} options={others} />
              <div style={{ marginTop: 10 }}>
                <button type="button" style={btnStyle("gold")} disabled={props.pickA === ""} onClick={() => props.submitAction(p, "Sunmark shot", [props.pickA], false, "", "lumination", true)}>
                  Declare shot
                </button>
              </div>
            </div>
          )}
        </div>
      ) : null}
      {useDay === "dayKill" ? (
        <div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>Secretly kill one other living player, submitted privately to the GM. Teammates are allowed. Self is not. Optional. Resolves at the end of Lumination. If it is blocked, the use is still spent{dd(props.state, "D48") ? " and you are told only that the kill failed" : ""}.{dd(props.state, "D47") && props.state.round === 1 ? " No day kill in Lumination 1 (Design default D47, Nov 21 audit): anything submitted now does nothing." : ""}</div>
          <ChargePip held={p.charges > 0} usedAt={p.usedAtDeaths} deaths={props.state.deathCount || 0} />
          <label style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
            <input type="checkbox" checked={props.skipKill} onChange={(e: ChangeEvent<HTMLInputElement>) => props.setSkipKill(e.target.checked)} />
            Hold the use (do not kill)
          </label>
          {props.skipKill ? null : <SelectList label="Target" value={props.pickA} onChange={props.setPickA} options={others} />}
          <div style={{ marginTop: 10 }}>
            <button
              type="button"
              style={btnStyle("gold")}
              disabled={!props.skipKill && props.pickA === ""}
              onClick={() => props.submitAction(p, "Red Scar day kill", props.skipKill ? [] : [props.pickA], props.skipKill, "", "lumination", !props.skipKill)}
            >
              Submit
            </button>
          </div>
        </div>
      ) : null}
      {useDay === "invite" ? (
        <div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>Invite any number of players this Lumination. Each must accept to join.</div>
          <SelectList label="Invite" value={props.pickA} onChange={props.setPickA} options={others.filter((o: { value: string }) => !playerById(props.state.players, o.value)?.syndicateMember)} />
          <div style={{ marginTop: 10 }}>
            <button type="button" style={btnStyle("gold")} disabled={props.pickA === ""} onClick={() => props.invitePlayer(p, props.pickA)}>
              Send invite
            </button>
          </div>
        </div>
      ) : null}
      {useDay === "summon" ? (
        <div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
            Summon two dead players. Need at least two Remnants. The same dead player can be summoned again later. They must vote as you vote (your vote counts as 3). Yes-or-no questions only, in the summon chat. This prototype allows summoning a dead Ashen.
            <PendingTag />
          </div>
          <ChargePip held={p.charges > 0} usedAt={p.usedAtDeaths} deaths={props.state.deathCount || 0} />
          {dead.length < 2 ? (
            <div style={{ color: C.muted }}>Fewer than two Remnants of the Vanished are available.</div>
          ) : (
            <div>
              <div style={wrap}>
                <SelectList label="First" value={props.pickA} onChange={props.setPickA} options={dead} />
                <SelectList label="Second" value={props.pickB} onChange={props.setPickB} options={dead} />
              </div>
              <div style={{ marginTop: 10 }}>
                <button
                  type="button"
                  style={btnStyle("gold")}
                  disabled={props.pickA === "" || props.pickB === "" || props.pickA === props.pickB}
                  onClick={() => props.submitAction(p, "Necroreclaimer summon", [props.pickA, props.pickB], false, "", "lumination", true)}
                >
                  Summon
                </button>
              </div>
            </div>
          )}
        </div>
      ) : null}
      {submitted ? (
        <div style={{ marginTop: 10, color: C.success, fontSize: 13 }}>
          Submitted: {submitted.label}
          {submitted.skip ? " (held)" : submitted.targets.length ? " — " + submitted.targets.map((id: string) => props.nameOf(id)).join(", ") : ""}
          {submitted.extra ? " · " + submitted.extra : ""}
        </div>
      ) : null}
    </div>
  );
}

function NominationForm(props: {
  state: GameState;
  player: Player;
  living: Player[];
  nominatePlayer: (playerId: string, targetId: string) => void;
}): ReactNode {
  const current = (props.state.nominations || {})[props.player.id] || "";
  const [choice, setChoice] = useState(current);
  const showVoice = props.player.roleId === "voice-of-the-accord";
  return (
    <div>
      {showVoice ? (
        <div style={{ marginBottom: 8, display: "inline-block", padding: "2px 8px", border: "1px solid " + C.goldHi, color: C.goldHi, fontFamily: FONT.label, letterSpacing: "0.12em", fontSize: 12 }}>
          ×2
          <PracticeTag />
        </div>
      ) : null}
      <SelectList
        label="Nominate"
        value={choice}
        onChange={setChoice}
        options={props.living.map((x: Player) => ({ value: x.id, label: x.name }))}
      />
      <div style={{ marginTop: 10 }}>
        <button
          type="button"
          style={btnStyle("gold")}
          disabled={choice === ""}
          onClick={() => props.nominatePlayer(props.player.id, choice)}
        >
          Submit nomination
        </button>
      </div>
      {current ? <div style={{ marginTop: 8, color: C.success, fontSize: 13 }}>You have nominated {nameOfFrom(props.state, current)}.</div> : null}
    </div>
  );
}

function VoteForm(props: { state: GameState; player: Player }): ReactNode {
  const nominees = props.state.nominees.filter((id: string) => id !== "");
  if (nominees.length === 0) {
    return <div style={{ color: C.muted }}>The ballot is not posted yet.</div>;
  }
  const current = props.state.votes[props.player.id] || "";
  const weight =
    props.player.roleId === "voice-of-the-accord"
      ? 2
      : props.player.roleId === "the-necroreclaimer" && props.state.summonedIds.length === 2
        ? 3
        : 1;
  return (
    <div>
      {weight > 1 ? (
        <div style={{ marginBottom: 8, display: "inline-block", padding: "2px 8px", border: "1px solid " + C.goldHi, color: C.goldHi, fontFamily: FONT.label, letterSpacing: "0.12em", fontSize: 12 }}>
          ×{weight}
          <PracticeTag />
        </div>
      ) : null}
      <VoteInner state={props.state} player={props.player} nominees={nominees} current={current} />
    </div>
  );
}

function VoteInner(props: { state: GameState; player: Player; nominees: string[]; current: string }): ReactNode {
  const [choice, setChoice] = useState(props.current);
  const [, setTick] = useState(0);
  void props.state;
  return (
    <div>
      <SelectList
        label="Execute"
        value={choice}
        onChange={setChoice}
        options={props.nominees.map((id: string) => ({
          value: id,
          label: nameOfFrom(props.state, id),
        }))}
      />
      <div style={{ marginTop: 10 }}>
        <CastVote playerId={props.player.id} choice={choice} weightHint={props.player.roleId === "voice-of-the-accord" ? 2 : props.player.roleId === "the-necroreclaimer" && props.state.summonedIds.length === 2 ? 3 : 1} onCast={() => setTick((n: number) => n + 1)} />
      </div>
      {props.current ? <div style={{ marginTop: 8, color: C.success, fontSize: 13 }}>You have voted for {nameOfFrom(props.state, props.current)}.</div> : null}
    </div>
  );
}

function CastVote(props: { playerId: string; choice: string; weightHint: number; onCast: () => void }): ReactNode {
  return <CastVoteBound {...props} />;
}

function CastVoteBound(props: { playerId: string; choice: string; weightHint: number; onCast: () => void }): ReactNode {
  const write = useVoteWriter();
  return (
    <button
      type="button"
      style={btnStyle("gold")}
      disabled={props.choice === ""}
      onClick={() => {
        write(props.playerId, props.choice);
        props.onCast();
      }}
    >
      Cast vote{props.weightHint > 1 ? " (counts as " + props.weightHint + ")" : ""}
    </button>
  );
}

let voteWriter: ((playerId: string, choice: string) => void) | null = null;
function useVoteWriter(): (playerId: string, choice: string) => void {
  return (playerId: string, choice: string) => {
    if (voteWriter) voteWriter(playerId, choice);
  };
}

type GmProps = {
  state: GameState;
  setState: (fn: (prev: GameState) => GameState) => void;
  drafts: Record<string, string>;
  setDraft: (c: string, v: string) => void;
  sendChat: (c: string, from: string) => void;
  nameOf: (id: string) => string;
  onDeal: () => void;
  onReassign: (playerId: string, roleId: string) => void;
  patchPlayer: (id: string, fn: (p: Player) => Player) => void;
  gmKill: (id: string, currentlyAlive: boolean) => void;
  enterFlip: (heads: boolean) => void;
};

function winnerLabel(w: Winner): string {
  if (w === "lumen") return "Lumen";
  if (w === "ashen") return "Ashen";
  if (w === "syndic") return "Syndic";
  if (w === "shadow") return "Shadow Blade";
  return "none";
}

const PORTAL_BEAT_MISSING =
  "Not written yet. The rulebook names this Portal Arc beat but does not include the narration text.";

function playerNeedsAshAction(state: GameState, p: Player): boolean {
  if (!p.alive) return false;
  const k = ashKindFor(state, p);
  const e = echoAshKind(state, p);
  if (hasInheritedKill(state, p)) return true;
  if (k !== "none" && k !== "auto") return true;
  if (e !== "none" && e !== "auto") return true;
  return false;
}

function buildAhsokaUpdate(state: GameState): string {
  const lines: string[] = [];
  lines.push("Ashes of Lumination — game update for Ahsoka");
  lines.push("Snapshot from the companion prototype. This is not a live feed, and this Page cannot reach Ahsoka.");
  lines.push("");
  lines.push("Round: " + (state.dealt ? String(state.round || 0) : "not dealt"));
  lines.push("Phase: " + phaseLabel(state.phase));
  lines.push("Winner: " + (state.winner !== "" ? winnerLabel(state.winner) : "none yet"));
  lines.push("");
  lines.push("Players (alive/dead, with roles)");
  if (state.players.length === 0) {
    lines.push("  No roles dealt yet. Setup names: " + state.setupNames.filter((n: string) => n.trim() !== "").join(", "));
  }
  for (const p of state.players) {
    const role = roleOf(p.roleId);
    const temp = p.tempRoleId !== "" ? " (temporary ability: " + roleOf(p.tempRoleId).name + ")" : "";
    lines.push(
      "  " +
        p.name +
        " — " +
        (p.alive ? "living" : "dead") +
        " — " +
        role.name +
        " (" +
        p.team +
        ")" +
        temp,
    );
    const soul = p.soulboundWith !== "" ? nameOfFrom(state, p.soulboundWith) : "none";
    const chargeBit = role.charged || p.charges > 0 ? "; Charges: " + p.charges : "";
    lines.push(
      "    Ash Touched: " +
        (p.ashTouched ? "yes" : "no") +
        "; Mire Touched: " +
        (p.mireTouched ? "yes" : "no") +
        "; Poison count: " +
        p.poisonCount +
        "/3; Shielded: " +
        (p.shielded ? "yes" : "no") +
        "; Soulbound: " +
        soul +
        "; Failsafe-cancelled: " +
        (p.failsafeCancelled ? "yes" : "no") +
        "; Syndicate: " +
        (p.syndicateMember ? "yes" : "no") +
        "; Vote silenced: " +
        (p.voteSilenced ? "yes" : "no") +
        chargeBit,
    );
  }
  lines.push("");
  lines.push("Table state");
  const suc = playerById(state.players, state.successorId);
  lines.push("  The Ashen Tyrant has died: " + (state.tyrantHasDied ? "yes" : "no"));
  lines.push("  Night of peace: " + (state.nightOfPeace ? "yes" : "no") + ((state.peaceRound || 0) > 0 ? " (peace Ash Fall " + state.peaceRound + ", inherited kill from Ash Fall " + (state.peaceRound + 1) + ")" : ""));
  lines.push("  Shadow Blade takeover: " + (state.shadowTakeover ? "yes (secret — former Ashen are not told)" : "no"));
  lines.push("  Watching Eye: " + (Boolean(state.eyeFound) ? "found the Ash Touched player, no further checks" : state.tyrantHasDied ? "no further checks (The Ashen Tyrant is dead)" : "still hunting"));
  lines.push("  Inherited killer: " + (suc ? suc.name + " (" + roleOf(suc.roleId).name + ")" : "none") + "; succession passes used: " + (state.successionPasses || 0) + " of 2");
  lines.push(
    "  Echo Thief copy: " +
      (state.echoCopyRoleId !== "" ? roleOf(state.echoCopyRoleId).name + (state.echoCopySpent ? " (spent uses carried over)" : "") : "none"),
  );
  lines.push("  Paradox coin flip used: " + (state.paradoxFlipUsed ? "yes" : "no") + "; converted: " + (state.paradoxConverted ? "yes" : "no") + "; flip pending: " + (state.pendingParadoxFlip ? "yes" : "no"));
  lines.push("  Syndic death pending: " + (state.pendingSyndicDeath ? "yes" : "no"));
  const ddOff = DESIGN_DEFAULTS.filter((d) => !dd(state, d.id)).map((d) => d.id);
  lines.push("  Design defaults (Nov 21 audit, pending Caden): " + (ddOff.length ? "off: " + ddOff.join(", ") + "; all others on" : "all on"));
  if (state.pendingPoisonDeathIds.length > 0) {
    lines.push("  Queued three-poison deaths: " + state.pendingPoisonDeathIds.map((id: string) => nameOfFrom(state, id)).join(", "));
  }
  if (state.summonedIds.length > 0) {
    lines.push("  Necroreclaimer summons this day: " + state.summonedIds.map((id: string) => nameOfFrom(state, id)).join(", "));
  }
  const masked = Object.keys(state.mindMasks);
  if (masked.length > 0) {
    lines.push(
      "  Ashen Mind disguises this round: " +
        masked
          .map((id: string) => nameOfFrom(state, id) + " shown as " + roleOf(state.mindMasks[id] || "").name)
          .join("; "),
    );
  }
  lines.push("");
  lines.push("Submitted actions this round (round " + (state.round || 0) + ")");
  const nightActs = state.actions.filter((a: ActionSub) => a.round === state.round && a.phase === "ashFall");
  const dayActs = state.actions.filter((a: ActionSub) => a.round === state.round && a.phase === "lumination");
  if (nightActs.length === 0) lines.push("  Ash Fall: none submitted yet.");
  for (const a of nightActs) {
    lines.push(
      "  Ash Fall — " +
        nameOfFrom(state, a.playerId) +
        " · " +
        a.label +
        (a.skip ? " · skip" : a.targets.length ? " · " + a.targets.map((id: string) => nameOfFrom(state, id)).join(", ") : "") +
        (a.extra ? " · " + a.extra : ""),
    );
  }
  if (dayActs.length === 0) lines.push("  Lumination: none submitted yet.");
  for (const a of dayActs) {
    lines.push(
      "  Lumination — " +
        nameOfFrom(state, a.playerId) +
        " · " +
        a.label +
        (a.skip ? " · held" : a.targets.length ? " · " + a.targets.map((id: string) => nameOfFrom(state, id)).join(", ") : "") +
        (a.extra ? " · " + a.extra : ""),
    );
  }
  lines.push("");
  lines.push("Resolved results this round");
  const roundResults = state.results.filter((r: ResultMsg) => r.round === state.round);
  if (roundResults.length === 0 && state.publicNotices.length === 0) lines.push("  None yet.");
  for (const r of roundResults) {
    lines.push("  To " + nameOfFrom(state, r.playerId) + ": " + r.text);
  }
  for (const n of state.publicNotices) {
    lines.push("  Public: " + n);
  }
  lines.push("");
  lines.push("Votes and executions");
  const noms = state.nominees.filter((id: string) => id !== "");
  lines.push("  Nominees: " + (noms.length ? noms.map((id: string) => nameOfFrom(state, id)).join(", ") : "none posted"));
  const voteKeys = Object.keys(state.votes);
  if (voteKeys.length === 0) lines.push("  Votes: none yet.");
  for (const vid of voteKeys) {
    const voter = playerById(state.players, vid);
    const w = voter ? voteWeight(state, voter) : 1;
    lines.push("  " + nameOfFrom(state, vid) + " (weight " + w + ") → " + nameOfFrom(state, state.votes[vid] || ""));
  }
  if (state.hadExecution && state.lastExecutedName !== "") {
    lines.push("  Execution this Dawn Accord: " + state.lastExecutedName + " (" + roleOf(state.lastExecutedRoleId).name + ")");
  } else {
    lines.push("  Execution this Dawn Accord: none yet");
  }
  lines.push("");
  lines.push("Latest log (up to 20, oldest first)");
  const latest = state.log.slice(0, 20).slice().reverse();
  if (latest.length === 0) lines.push("  (empty)");
  for (const item of latest) {
    lines.push("  • " + item.text);
  }
  return lines.join("\n");
}

function buildReminders(state: GameState): string[] {
  const out: string[] = [];
  if (!state.dealt) {
    out.push("Roles are not dealt yet. Enter 5–20 names and deal before play begins.");
    return out;
  }
  if (state.pendingParadoxFlip) {
    out.push("The Luminary Paradox coin flip is pending. Flip a real coin and enter Heads or Tails.");
  }
  if (state.tyrantHasDied && (state.peaceRound || 0) > 0 && state.round <= (state.peaceRound || 0)) {
    const holder = playerById(state.players, state.successorId);
    const hn = holder ? holder.name + " (" + roleOf(holder.roleId).name + ")" : "the heir";
    out.push(
      (state.phase === "ashFall" && state.round === state.peaceRound ? "Night of peace is active. " : "A night of peace is pending. ") +
        peaceLine(state, hn) +
        " Other lethal abilities still work, including a converted Paradox's own kill (Caden, Nov 18 card).",
    );
  }
  if (state.shadowTakeover) {
    out.push("Shadow Blade takeover is in effect and is secret — do not announce it. Former Ashen are not told who is killing (Caden); they can help or sabotage. The Blade wins completely alone; former Ashen do not share the win (Caden Nov 16; Caden, Nov 17 card). Killing the active Shadow Blade is an immediate Lumen victory.");
  }
  const eye = state.players.find((p: Player) => p.roleId === "the-watching-eye" && p.alive);
  if (eye && state.winner === "") {
    const why = eyeDoneReason(state, eye);
    out.push(
      why !== ""
        ? "The Watching Eye (" + eye.name + ") has no further checks: " + (Boolean(state.eyeFound) ? "it found the Ash Touched player." : "The Ashen Tyrant is dead.") + " (Caden ruling: it never reveals the current killer or The Shadow Blade.)"
        : "The Watching Eye (" + eye.name + ") is still hunting. A hit reveals only The Ashen Tyrant; a Mire Touched target is cured with no information; a miss poisons a random player.",
    );
  }
  const civic = state.players.find((p: Player) => p.roleId === "the-civic-luminary" && p.alive);
  const livingN = livingPlayers(state.players).length;
  if (civic && state.winner === "" && livingN <= 6 && livingN > 4) {
    out.push("The Civic Luminary is alive and " + livingN + " players remain. If 4 remain after the Dawn Accord vote, the Lumen win.");
  }
  if (civic && state.winner === "" && livingN === 4) {
    out.push("4 players remain and The Civic Luminary is alive. If this is after the Dawn Accord vote, confirm the Lumen win check.");
  }
  const echo = state.players.find((p: Player) => p.roleId === "the-echo-thief" && p.alive);
  if (echo) {
    if (state.phase === "dawnAccord" && state.hadExecution) {
      out.push(
        "Echo Thief copy refresh: it copies " +
          (state.lastExecutedRoleId !== "" ? roleOf(state.lastExecutedRoleId).name : "the executed player's ability") +
          (state.lastExecutedName !== "" ? " (" + state.lastExecutedName + ")" : "") +
          " for the following round. Tell them the role name privately.",
      );
    } else if (state.phase === "dawnAccord" && !state.hadExecution) {
      out.push(
        "If nobody is executed, The Echo Thief keeps its previous copied ability (" +
          (state.echoCopyRoleId !== "" ? roleOf(state.echoCopyRoleId).name : "none yet") +
          "); spent uses stay spent.",
      );
    } else if (state.echoCopyRoleId !== "") {
      out.push(
        "The Echo Thief's current copy is " +
          roleOf(state.echoCopyRoleId).name +
          (state.echoCopySpent ? " (spent uses carried over)." : "."),
      );
    }
  }
  for (const p of livingPlayers(state.players)) {
    if (p.poisonCount === 2) {
      out.push(p.name + " is at 2/3 successful poisons. One more successful poison means death the following night.");
    }
    if (p.poisonCount >= 3) {
      out.push(p.name + " is at 3/3 poisons and is queued for a three-poison death on an unprotected Ash Fall.");
    }
  }
  if (state.pendingSyndicDeath) {
    out.push("The Syndic is due to die on a coming Ash Fall because an Ashen joined the syndicate.");
  }
  if (state.phase === "ashFall" && state.winner === "") {
    const waiting = livingPlayers(state.players).filter(
      (p: Player) => playerNeedsAshAction(state, p) && !actionFor(state, p.id, "ashFall"),
    );
    if (waiting.length > 0) {
      out.push(
        "Ash Fall actions not yet submitted: " +
          waiting.map((p: Player) => p.name + " (" + roleOf(effectiveRoleId(p)).name + ")").join(", ") +
          ".",
      );
    }
  }
  if (state.phase === "lumination" && state.winner === "") {
    for (const p of livingPlayers(state.players)) {
      const day = roleOf(effectiveRoleId(p)).day;
      const copiedDay =
        p.roleId === "the-echo-thief" && state.echoCopyRoleId !== "" ? roleOf(state.echoCopyRoleId).day : "none";
      const useDay: DayKind = day !== "none" ? day : copiedDay;
      const charged = useDay === "question" || useDay === "shot" || useDay === "summon" || useDay === "dayKill";
      if (charged && p.charges > 0 && !actionFor(state, p.id, "lumination")) {
        out.push(
          p.name +
            " has " +
            p.charges +
            " charge(s) available and has not submitted a Lumination action yet (" +
            roleOf(effectiveRoleId(p)).name +
            ").",
        );
      }
    }
    const syn = livingPlayers(state.players).find((p: Player) => p.roleId === "the-syndic");
    if (syn) {
      const open = livingPlayers(state.players).filter((p: Player) => !p.syndicateMember);
      if (open.length > 0) {
        out.push("The Syndic may still invite: " + open.map((p: Player) => p.name).join(", ") + ".");
      }
    }
  }
  if (state.phase === "dawnAccord" && state.winner === "") {
    const noms = state.nominees.filter((id: string) => id !== "");
    if (noms.length < 3) {
      out.push("Dawn Accord ballot has " + noms.length + " names. It is built from the nominations: the top 3, everyone who ties for the last seat, and No execution only when fewer than 3 living players were nominated.");
    }
    if (noms.length > 0) {
      const missing = livingPlayers(state.players).filter((p: Player) => !p.voteSilenced && !state.votes[p.id]);
      if (missing.length > 0) {
        out.push("Votes not yet in: " + missing.map((p: Player) => p.name).join(", ") + ".");
      }
      if (!state.hadExecution) {
        out.push("No execution has been entered yet this Dawn Accord. Resolving applies the votes: a unique leader is executed, and a tie or a lead for No execution means nobody is executed.");
      }
    }
  }
  const atN = state.players.filter((p: Player) => p.ashTouched).length;
  if (state.dealt && atN === 0) {
    out.push("No player is marked Ash Touched. Caden: exactly 1 per game, placed by the GM for balance and fun. Placement guidance: [placeholder — Ahsoka is writing it]. Set it on the modifier tracker.");
  } else if (atN > 1) {
    out.push(atN + " players are marked Ash Touched. Caden: exactly 1 per game. Clear the extras on the modifier tracker.");
  }
  if (state.phase === "dawnAccord" && state.winner === "") {
    const dv = deadVoteInfo(state);
    if (dv.deadCast.length > 0) {
      out.push(
        "Dead votes (Caden, Nov 18): only the first 3 dead votes count each Accord; later dead voters get \"Max votes reached\". A dead Voice of the Accord counts as 1. Dead votes counted: " +
          dv.counted.length +
          " of 3" +
          (dv.dropped.length ? ". Not counted, final vote kept: " + dv.dropped.map((id: string) => nameOfFrom(state, id)).join(", ") + " (over the limit; Caden)" : "") +
          ".",
      );
    }
  }
  const armed = livingPlayers(state.players).filter((p: Player) => p.syndShieldArmed);
  if (state.phase === "ashFall" && armed.length > 0) {
    out.push("Syndicate shield set for tonight: " + armed.map((p: Player) => p.name).join(", ") + " (one-time, Caden).");
  }
  if (cutoffApplies(state)) {
    const ci = cutoffInfo(state);
    out.push("Test rule ON: 75% succession cutoff. Once The Ashen Tyrant is dead, the Lumen win as soon as living Lumen are " + ci.threshold + " or fewer (of " + ci.start + " dealt) while a non-Blade Ashen holds or would receive the kill. Now: " + ci.living + " living Lumen.");
  }
  if (state.dealt && soulboundRequired(state) && !hasSoulboundPair(state)) {
    out.push("Soulbound is required in every game with 10 or more players (Caden, Nov 18), and no pair is placed. Set one on the modifier tracker (or use Suggest a Soulbound pair in Setup).");
  }
  const bound = state.players.filter((p: Player) => p.soulboundWith !== "" && p.alive);
  if (bound.length > 0) {
    out.push("Soulbound (Caden: if one dies, both die): " + bound.map((p: Player) => p.name + " ↔ " + nameOfFrom(state, p.soulboundWith)).join(", ") + ". They are not told they are bound (Caden, Nov 17 card); nothing on a player screen reveals it. A shield saves the partner of a Soulbound player who dies, but a shield never stops execution (Caden, Nov 21).");
  }
  if (state.tyrantHasDied && sucName(state) !== "") {
    out.push("Tyrant succession: " + sucName(state) + " holds the inherited kill" + (inheritedKillPaused(state) ? " after the night of peace (first kill on Ash Fall " + ((state.peaceRound || 0) + 1) + ")" : "") + ". Passes used: " + (state.successionPasses || 0) + " of 2 (Caden, Nov 18: Red Scar, then Mirebane, then Echo Thief; a Blade takeover is not counted, Caden's Nov 18 card).");
  }
  const convertedPara = state.paradoxConverted ? state.players.find((p: Player) => p.roleId === "the-luminary-paradox" && p.team === "Ashen" && p.alive) : undefined;
  if (convertedPara) {
    out.push("Converted Paradox: " + convertedPara.name + " has its own kill every Ash Fall, separate from the Tyrant's (Caden, Nov 18), so 2 deaths a night are possible. Caden (Nov 18 card): it keeps its kill after the Tyrant dies; a night of peace does not pause it (Caden, Nov 18 card: \"Yes, the Paradox still kills\").");
  }
  if (state.phase === "setup" && state.dealt) {
    out.push("Start-of-game results should already be in for The Lumen Bearer and The Quadrant Judge. Begin Round 1 when ready.");
  }
  return out;
}

function sucName(state: GameState): string {
  const suc = playerById(state.players, state.successorId);
  return suc ? suc.name + " (" + roleOf(suc.roleId).name + ")" : "";
}

function portalStory(state: GameState): { heading: string; body: string } {
  if (state.winner === "lumen") {
    return { heading: "Ending — Lumen victory", body: PORTAL_BEAT_MISSING };
  }
  if (state.winner === "ashen") {
    return { heading: "Ending — Ashen victory", body: PORTAL_BEAT_MISSING };
  }
  if (state.winner === "syndic") {
    return { heading: "Ending — Syndic victory", body: PORTAL_BEAT_MISSING };
  }
  if (state.winner === "shadow") {
    return {
      heading: "Ending — Shadow Blade victory",
      body: "Not written yet. The Portal Arc lists three Endings (Lumen, Ashen, Syndic) and does not include a Shadow Blade ending or its narration.",
    };
  }
  if (!state.dealt || state.phase === "setup" || state.round === 0) {
    return { heading: "Beginning", body: PORTAL_BEAT_MISSING };
  }
  if (state.phase === "ashFall") {
    const n = state.round;
    if (n >= 1 && n <= 10) {
      return { heading: "Night " + n + " kill narration (current Ash Fall)", body: PORTAL_BEAT_MISSING };
    }
    return {
      heading: "Night " + n + " kill narration (current Ash Fall)",
      body: "Not written yet. The rulebook only frames Night 1–10 kill narrations.",
    };
  }
  const next = state.round + 1;
  if (next >= 1 && next <= 10) {
    return { heading: "Night " + next + " kill narration (next Ash Fall)", body: PORTAL_BEAT_MISSING };
  }
  return {
    heading: "Night " + next + " kill narration (next Ash Fall)",
    body: "Not written yet. The rulebook only frames Night 1–10 kill narrations.",
  };
}

function AhsokaPanel(props: { state: GameState; setState: (fn: (prev: GameState) => GameState) => void }): ReactNode {
  const theme = useGrokTheme();
  const update = buildAhsokaUpdate(props.state);
  const reminders = buildReminders(props.state);
  const beat = portalStory(props.state);
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    setCopied(false);
  }, [update]);
  const onCopy = () => {
    if (typeof navigator !== "undefined" && navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
      navigator.clipboard.writeText(update).then(() => setCopied(true)).catch(() => setCopied(false));
      return;
    }
    setCopied(false);
  };
  return (
    <SectionCard
      title="Ahsoka"
      note="Ahsoka Tano is your design partner and GM advisor. This Page cannot reach her live. Copy the snapshot or draft a note, then share it with her outside this prototype."
    >
      <div style={{ color: C.gold, fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Game update for Ahsoka</div>
      <textarea
        readOnly
        value={update}
        style={{ ...inputStyle(), minHeight: 220, resize: "vertical", fontFamily: theme.font.mono, fontSize: 12, lineHeight: 1.45, whiteSpace: "pre-wrap" }}
      />
      <div style={{ ...wrap, marginTop: 8, marginBottom: 16 }}>
        <button type="button" style={btnStyle("gold")} onClick={onCopy}>
          {copied ? "Copied" : "Copy update"}
        </button>
        {copied ? <span style={{ color: C.success, fontSize: 13 }}>The snapshot is on your clipboard.</span> : null}
      </div>

      <div style={{ color: C.gold, fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Don't forget</div>
      <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
        These reminders are generated by the app from the current game state. They are not from Ahsoka.
      </div>
      {reminders.length > 0 ? (
        <div>
          {reminders.map((item: string, i: number) => (
            <div key={i} style={{ display: "flex", gap: 8, alignItems: "flex-start", marginBottom: 8 }}>
              <span style={{ color: C.ember, marginTop: 2 }}>›</span>
              <div style={{ fontSize: 14, lineHeight: 1.45, color: C.text }}>{item}</div>
            </div>
          ))}
        </div>
      ) : (
        <div style={{ color: C.muted, fontSize: 14, marginBottom: 8 }}>The app has nothing it needs to flag in this state.</div>
      )}

      <div style={{ color: C.gold, fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", margin: "16px 0 6px" }}>Next story beat</div>
      <div style={{ color: C.text, fontSize: 16, marginBottom: 6 }}>{beat.heading}</div>
      <div style={{ fontSize: 14, lineHeight: 1.5, color: C.text, whiteSpace: "pre-wrap" }}>{beat.body}</div>

      <div style={{ color: C.gold, fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", margin: "16px 0 6px" }}>
        Ahsoka chat (coming in the multiplayer build)
      </div>
      <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
        This box does not send. Nothing you type here is delivered to Ahsoka. Draft a note for later, and paste a reply she gives you elsewhere so it stays saved with this game.
      </div>
      <label style={{ display: "block", marginBottom: 10 }}>
        <span style={labelStyle()}>Your draft (not sent)</span>
        <textarea
          style={{ ...inputStyle(), minHeight: 90, resize: "vertical" }}
          value={props.state.ahsokaDraft}
          placeholder="Notes for Ahsoka — not sent from this Page."
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            props.setState((s: GameState) => ({ ...s, ahsokaDraft: e.target.value }))
          }
        />
      </label>
      <label style={{ display: "block" }}>
        <span style={labelStyle()}>Ahsoka's reply (paste to keep it with the game)</span>
        <textarea
          style={{ ...inputStyle(), minHeight: 90, resize: "vertical" }}
          value={props.state.ahsokaReply}
          placeholder="Paste a reply from Ahsoka here. It is stored with this game only."
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            props.setState((s: GameState) => ({ ...s, ahsokaReply: e.target.value }))
          }
        />
      </label>
    </SectionCard>
  );
}

function gmView(props: GmProps): ReactNode {
  const state = props.state;
  voteWriter = (playerId: string, choice: string) => {
    props.setState((prev: GameState) => castPlayerVote(prev, playerId, choice));
  };

  const tally = tallies(state);
  const focus = playerById(state.players, state.gmFocus);
  const nightActs = state.actions.filter((a: ActionSub) => a.round === state.round && a.phase === "ashFall");
  const dayActs = state.actions.filter((a: ActionSub) => a.round === state.round && a.phase === "lumination");
  const living = livingPlayers(state.players);
  const ashenMsgs = state.chats.filter((m: ChatMsg) => m.channel === "ashen");
  const focusMsgs = focus ? state.chats.filter((m: ChatMsg) => m.channel === "gm:" + focus.id) : [];

  return (
    <div>
      {state.pendingParadoxFlip ? (
        <SectionCard title="The Luminary Paradox — coin flip" note="The rulebook: flip a real coin and enter the result.">
          <div style={wrap}>
            <button type="button" style={btnStyle("gold")} onClick={() => props.enterFlip(true)}>
              Heads — stays Lumen
            </button>
            <button type="button" style={btnStyle("ember")} onClick={() => props.enterFlip(false)}>
              Tails — becomes Ashen
            </button>
          </div>
        </SectionCard>
      ) : null}

      {state.winner !== "" ? (
        <SectionCard title="Game over">
          <div style={{ fontSize: 20, color: C.gold }}>
            {state.winner === "lumen"
              ? "The Lumen have won."
              : state.winner === "ashen"
                ? "The Ashen have won."
                : state.winner === "syndic"
                  ? "The Syndic and its living recruits have won. Dead recruits do not share the win."
                  : "The Shadow Blade has won completely alone. Former Ashen do not share the win."}
          </div>
        </SectionCard>
      ) : null}

      <SectionCard title="Phase controller">
        <div style={wrap}>
          {state.phase === "setup" && state.dealt && soulboundRequired(state) && !hasSoulboundPair(state) ? (
            <div style={{ flex: "1 1 100%", color: C.ember, fontSize: 14 }}>
              Soulbound is required in every game with 10 or more players (Caden, Nov 18). Pick a pair on the modifier tracker, or suggest one, before Round 1.{" "}
              <button type="button" style={btnStyle("quiet")} onClick={() => props.setState((s: GameState) => suggestSoulboundPair(s))}>
                Suggest a Soulbound pair
              </button>
            </div>
          ) : null}
          {state.phase === "setup" && state.dealt ? (
            <button
              type="button"
              style={btnStyle("gold")}
              disabled={soulboundRequired(state) && !hasSoulboundPair(state)}
              onClick={() => props.setState((s: GameState) => startRound(s, true))}
            >
              Begin Round 1 — Ash Fall
            </button>
          ) : null}
          {state.phase === "ashFall" ? (
            <button type="button" style={btnStyle("gold")} onClick={() => props.setState((s: GameState) => resolveAshFall(s))}>
              Resolve Ash Fall → Lumination
            </button>
          ) : null}
          {state.phase === "lumination" ? (
            <button type="button" style={btnStyle("gold")} onClick={() => props.setState((s: GameState) => resolveLumination(s))}>
              Resolve Lumination → Dawn Accord
            </button>
          ) : null}
          {state.phase === "dawnAccord" ? (
            <button type="button" style={btnStyle("quiet")} onClick={() => props.setState((s: GameState) => closeDawnAccord(s))}>

              Next round — Ash Fall
            </button>
          ) : null}
        </div>
      </SectionCard>

      <AhsokaPanel state={state} setState={props.setState} />

      {state.phase === "setup" ? (
        <SectionCard title="Setup" note={distributionLabel(state.setupNames.filter((n: string) => n.trim() !== "").length || 8, state.unalignedPick, state.rechargeAt)}>
          {state.setupNames.map((name: string, i: number) => (
            <div key={i} style={{ ...wrap, marginBottom: 8 }}>
              <label style={{ flex: "1 1 200px" }}>
                <span style={labelStyle()}>Player {i + 1}</span>
                <input
                  style={inputStyle()}
                  value={name}
                  onChange={(e: ChangeEvent<HTMLInputElement>) =>
                    props.setState((s: GameState) => {
                      const names = s.setupNames.slice();
                      names[i] = e.target.value;
                      return { ...s, setupNames: names };
                    })
                  }
                />
              </label>
              {state.setupNames.length > 5 ? (
                <button
                  type="button"
                  style={btnStyle("quiet")}
                  onClick={() =>
                    props.setState((s: GameState) => ({
                      ...s,
                      setupNames: s.setupNames.filter((_: string, idx: number) => idx !== i),
                    }))
                  }
                >
                  Remove
                </button>
              ) : null}
            </div>
          ))}
          <div style={{ ...wrap, margin: "8px 0 12px" }}>
            <div style={{ flex: "1 1 200px", color: C.muted, fontSize: 14, lineHeight: 1.5 }}>
              <span style={labelStyle()}>Recharge (Caden's 5-player rule)</span>
              A used ability comes back only after 5 more players have died since it was used. No setting needed.
            </div>
            <label style={{ flex: "1 1 200px" }}>
              <span style={labelStyle()}>Ash Touched: chance of a false result (%) — a balance lever (Caden)</span>
              <input
                style={inputStyle()}
                type="number"
                min={0}
                max={100}
                value={clampPct(state.atFalsePct)}
                onChange={(e: ChangeEvent<HTMLInputElement>) =>
                  props.setState((st: GameState) => ({ ...st, atFalsePct: clampPct(Number(e.target.value)) }))
                }
              />
            </label>
            <label style={{ flex: "1 1 200px" }}>
              <span style={labelStyle()}>Unaligned at 7–9 players</span>
              <select
                style={inputStyle()}
                value={String(state.unalignedPick)}
                onChange={(e: ChangeEvent<HTMLSelectElement>) =>
                  props.setState((st: GameState) => ({ ...st, unalignedPick: Number(e.target.value) }))
                }
              >
                <option value="-1">Random (0 or 1)</option>
                <option value="0">0 Unaligned</option>
                <option value="1">1 Unaligned</option>
              </select>
            </label>
            {state.setupNames.filter((n: string) => n.trim() !== "").length >= 7 ? (
              <label style={{ flex: "1 1 100%", display: "flex", gap: 8, alignItems: "flex-start", color: C.text, fontSize: 14 }}>
                <input
                  type="checkbox"
                  checked={state.testCutoff75 === true}
                  onChange={(e: ChangeEvent<HTMLInputElement>) => props.setState((st: GameState) => ({ ...st, testCutoff75: e.target.checked }))}
                />
                <span>
                  <strong>Test rule: 75% succession cutoff</strong> (off by default; for playtesting, not a core rule). Once The Ashen Tyrant is dead, if
                  living Lumen are at or below 75% of the starting Lumen while a non-Blade Ashen holds or would receive the kill, the Lumen win right away.
                  The Shadow Blade can still take over. Caden, Nov 18 card.
                </span>
              </label>
            ) : (
              <div style={{ flex: "1 1 100%", color: C.muted, fontSize: 13 }}>Test rule: 75% succession cutoff — not used at 5–6 players (1 Ashen, no one can inherit).</div>
            )}
            <div style={{ flex: "1 1 100%", borderTop: "1px solid " + C.goldDim, paddingTop: 8, marginTop: 4 }}>
              <div style={{ color: C.text, fontSize: 14, marginBottom: 4 }}>
                <strong>Design defaults (Nov 21 rulebook audit) — Default pending Caden.</strong> On matches the audited rulebook; off restores the app's earlier behaviour.
              </div>
              <div style={{ display: "flex", gap: 8, marginBottom: 6 }}>
                <button type="button" style={btnStyle("quiet")} onClick={() => props.setState((st: GameState) => ({ ...st, designDefaults: {} }))}>All on</button>
                <button
                  type="button"
                  style={btnStyle("quiet")}
                  onClick={() => props.setState((st: GameState) => ({ ...st, designDefaults: Object.fromEntries(DESIGN_DEFAULTS.map((d) => [d.id, false])) }))}
                >
                  All off
                </button>
              </div>
              {DESIGN_DEFAULTS.map((d) => (
                <label key={d.id} style={{ display: "flex", gap: 8, alignItems: "flex-start", color: C.text, fontSize: 13, marginBottom: 4 }}>
                  <input
                    type="checkbox"
                    checked={dd(state, d.id)}
                    onChange={(e: ChangeEvent<HTMLInputElement>) =>
                      props.setState((st: GameState) => ({ ...st, designDefaults: { ...(st.designDefaults || {}), [d.id]: e.target.checked } }))
                    }
                  />
                  <span>
                    <strong>
                      {d.id} {d.title}
                    </strong>{" "}
                    — Default pending Caden. On: {d.on} Off: {d.off}
                  </span>
                </label>
              ))}
            </div>
          </div>
          <div style={wrap}>
            {state.setupNames.length < 20 ? (
              <button
                type="button"
                style={btnStyle("quiet")}
                onClick={() =>
                  props.setState((s: GameState) => ({
                    ...s,
                    setupNames: s.setupNames.concat(["Player " + (s.setupNames.length + 1)]),
                  }))
                }
              >
                Add player
              </button>
            ) : null}
            <button
              type="button"
              style={btnStyle("quiet")}
              onClick={() => props.setState((s: GameState) => ({ ...s, setupNames: SAMPLE_NAMES.slice(), dealt: false, players: [] }))}
            >
              Load sample table (8 players)
            </button>
            <button
              type="button"
              style={btnStyle("gold")}
              disabled={state.setupNames.filter((n: string) => n.trim() !== "").length < 5}
              onClick={props.onDeal}
            >
              Deal roles
            </button>
          </div>
        </SectionCard>
      ) : null}

      {state.dealt ? (
        <SectionCard title="Players">
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13, minWidth: 640 }}>
              <thead>
                <tr style={{ color: C.muted, textAlign: "left" }}>
                  <th style={{ padding: "6px 8px" }}>Name</th>
                  <th style={{ padding: "6px 8px" }}>Role</th>
                  <th style={{ padding: "6px 8px" }}>Team</th>
                  <th style={{ padding: "6px 8px" }}>Status</th>
                  <th style={{ padding: "6px 8px" }}>Modifiers</th>
                  <th style={{ padding: "6px 8px" }}></th>
                </tr>
              </thead>
              <tbody>
                {state.players.map((p: Player) => (
                  <tr
                    key={p.id}
                    onClick={() => props.setState((s: GameState) => ({ ...s, gmFocus: p.id }))}
                    style={{
                      background: state.gmFocus === p.id ? C.surface2 : "transparent",
                      cursor: "pointer",
                      borderTop: "1px solid " + C.border,
                      color: p.alive ? C.text : C.dead,
                    }}
                  >
                    <td style={{ padding: "8px" }}>{p.name}</td>
                    <td style={{ padding: "8px" }}>
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center" }}>
                        <RolePortrait roleId={p.roleId} kind="tiny" name={roleOf(p.roleId).name} />
                        {state.phase === "setup" ? (
                          <select
                            style={{ ...inputStyle(), minHeight: 36, fontSize: 13, flex: "1 1 140px" }}
                            value={p.roleId}
                            onChange={(e: ChangeEvent<HTMLSelectElement>) => props.onReassign(p.id, e.target.value)}
                          >
                            {ROLES.map((r: RoleDef) => (
                              <option key={r.id} value={r.id}>
                                {r.name}
                              </option>
                            ))}
                          </select>
                        ) : (
                          <span>
                            {roleOf(p.roleId).name}
                            {p.tempRoleId !== "" ? " → " + roleOf(p.tempRoleId).name : ""}
                          </span>
                        )}
                      </div>
                    </td>
                    <td style={{ padding: "8px", color: teamColor(p.team) }}>
                      <span style={{ display: "inline-flex", alignItems: "center" }}>
                        <FactionChip team={p.team} />
                        {p.team}
                      </span>
                    </td>
                    <td style={{ padding: "8px" }}>{p.alive ? "Living" : "Vanished"}</td>
                    <td style={{ padding: "8px", color: C.muted }}>{modifierSummary(p)}</td>
                    <td style={{ padding: "8px" }}>
                      <button type="button" style={btnStyle(p.alive ? "danger" : "quiet")} onClick={() => props.gmKill(p.id, p.alive)}>
                        {p.alive ? "Kill" : "Revive"}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </SectionCard>
      ) : null}

      {focus ? (
        <SectionCard title={"Modifier tracker — " + focus.name}>
          <ModifierForm player={focus} players={state.players} patchPlayer={props.patchPlayer} />
          {roleOf(focus.roleId).charged || focus.tempRoleId !== "" ? (
            <label style={{ display: "block", marginTop: 10 }}>
              <span style={labelStyle()}>Charges (Red Scar / Self Known / Sunmark Shooter / Necroreclaimer)</span>
              <input
                style={inputStyle()}
                value={String(focus.charges)}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const n = parseInt(e.target.value, 10);
                  props.patchPlayer(focus.id, (p: Player) => ({ ...p, charges: isNaN(n) ? p.charges : Math.max(0, n) }));
                }}
              />
            </label>
          ) : null}
        </SectionCard>
      ) : null}

      {focus ? (
        <SectionCard title={"Private chat with " + focus.name}>
          <div style={wrap}>
            {state.players.map((p: Player) => (
              <button key={p.id} type="button" style={btnStyle(state.gmFocus === p.id ? "gold" : "quiet")} onClick={() => props.setState((s: GameState) => ({ ...s, gmFocus: p.id }))}>
                {p.name}
              </button>
            ))}
          </div>
          <div style={{ marginTop: 10 }}>
            <ChatPane
              fontFamily=""
              messages={focusMsgs}
              draft={props.drafts["gm:" + focus.id] || ""}
              onDraft={(v: string) => props.setDraft("gm:" + focus.id, v)}
              onSend={() => props.sendChat("gm:" + focus.id, "gm")}
              placeholder={"Message " + focus.name + "…"}
              nameOf={props.nameOf}
            />
          </div>
          {state.results.filter((r: ResultMsg) => r.playerId === focus.id).length > 0 ? (
            <div style={{ marginTop: 12 }}>
              <div style={labelStyle()}>Results sent to this player</div>
              {state.results
                .filter((r: ResultMsg) => r.playerId === focus.id)
                .map((r: ResultMsg) => (
                  <div key={r.id} style={{ fontSize: 13, marginBottom: 6, color: C.muted }}>
                    {r.text}
                  </div>
                ))}
            </div>
          ) : null}
          {focus.roleId === "the-self-known" || effectiveRoleId(focus) === "the-self-known" ? (
            <SelfKnownAnswer state={state} setState={props.setState} />
          ) : null}
        </SectionCard>
      ) : null}

      {state.players.some((p: Player) => p.team === "Ashen") ? (
        <SectionCard title="Ashen team chat" note="GM can read and write here. Players only see this on Ashen devices.">
          <ChatPane
            fontFamily=""
            messages={ashenMsgs}
            draft={props.drafts["ashen-gm"] || ""}
            onDraft={(v: string) => props.setDraft("ashen-gm", v)}
            onSend={() => {
              const text = (props.drafts["ashen-gm"] || "").trim();
              if (text === "") return;
              props.setState((prev: GameState) => ({
                ...prev,
                chats: prev.chats.concat([{ id: uid(), channel: "ashen", from: "gm", text: text, ts: Date.now() }]),
              }));
              props.setDraft("ashen-gm", "");
            }}
            placeholder="Write as GM in the Ashen chat…"
            nameOf={props.nameOf}
          />
        </SectionCard>
      ) : null}

      {state.phase === "ashFall" || state.phase === "lumination" || state.phase === "dawnAccord" || nightActs.length > 0 || dayActs.length > 0 ? (
        <SectionCard title="Action Panel" note={"Round " + state.round + " · " + nightActs.length + " of living Ash Fall submissions recorded. Day actions also appear once Lumination starts. Last shots appear at the Dawn Accord."}>
          {nightActs.map((a: ActionSub) => (
            <div key={a.id} style={{ marginBottom: 6, fontSize: 14 }}>
              {props.nameOf(a.playerId)} · {a.label}
              {a.skip ? " · skip" : a.targets.length ? " · " + a.targets.map((id: string) => props.nameOf(id)).join(", ") : ""}
              {a.extra ? " · " + a.extra : ""}
            </div>
          ))}
          {dayActs.map((a: ActionSub) => (
            <div key={a.id} style={{ marginBottom: 6, fontSize: 14, color: C.lumen }}>
              {props.nameOf(a.playerId)} · {a.label}
              {a.skip ? " · held" : a.targets.length ? " · " + a.targets.map((id: string) => props.nameOf(id)).join(", ") : ""}
              {a.extra ? " · " + a.extra : ""}
            </div>
          ))}
          {state.actions.filter((a: ActionSub) => a.round === state.round && a.phase === "dawnAccord").map((a: ActionSub) => (
            <div key={a.id} style={{ marginBottom: 6, fontSize: 14, color: C.goldHi }}>
              {props.nameOf(a.playerId)} · {a.label}
              {a.skip ? " · skip" : a.targets.length ? " · " + a.targets.map((id: string) => props.nameOf(id)).join(", ") : ""}
              {a.extra ? " · " + a.extra : ""}
            </div>
          ))}
          {living.filter((p: Player) => state.phase === "ashFall" && !actionFor(state, p.id, "ashFall") && ashKindFor(state, p) !== "none" && ashKindFor(state, p) !== "auto").map((p: Player) => (
            <div key={p.id} style={{ color: C.muted, fontSize: 13, marginBottom: 4 }}>
              Waiting on {p.name}
            </div>
          ))}
        </SectionCard>
      ) : null}

      {state.phase === "dawnAccord" ? (
        <SectionCard title="Dawn Accord" note="Table practice: player nominations build the ballot (top 3, tie for last place all go on, No execution only if fewer than 3 were nominated). Most votes wins; a tie means no execution. The GM may override the ballot.">
          <PracticeTag />
          <div style={{ margin: "8px 0", color: C.text, fontSize: 13 }}>
            Public nominations (Caden: Silent Hand voids are listed as normal and only quietly dropped from the count): {publicNominationText(state)}.
          </div>
          <div style={{ margin: "0 0 8px", color: C.muted, fontSize: 13 }}>
            GM only (includes voids):{" "}
            {state.players
              .filter((p: Player) => (state.nominations || {})[p.id])
              .map((p: Player) => p.name + " → " + nameOfFrom(state, (state.nominations || {})[p.id] || "") + (nominationWeight(state, p) <= 0 ? " (void)" : p.roleId === "voice-of-the-accord" ? " ×2" : ""))
              .join("; ") || "none submitted"}
          </div>
          <div style={wrap}>
            {[0, 1, 2, 3].map((i: number) => (
              <SelectList
                key={i}
                label={"Ballot " + (i + 1)}
                value={state.nominees[i] || ""}
                onChange={(v: string) =>
                  props.setState((st: GameState) => {
                    const n = st.nominees.slice();
                    while (n.length <= i) n.push("");
                    n[i] = v;
                    return setDawnNominees(st, n);
                  })
                }
                options={living
                  .map((pl: Player) => ({ value: pl.id, label: pl.name }))
                  .concat([{ value: NO_EXEC, label: "No execution" }])}
              />
            ))}
          </div>
          {tally.length > 0 ? (
            <div style={{ marginTop: 12 }}>
              <div style={labelStyle()}>Public tally (Voice of the Accord ×2; Necroreclaimer with two summons ×3; Silent Hand = 0; first 3 dead votes count, a dead Voice counts as 1)</div>
              <div style={{ color: C.muted, fontSize: 13, marginBottom: 6 }}>
                {(() => {
                  const dv = deadVoteInfo(state);
                  return (
                    "Dead votes (Caden, Nov 18): the first 3 dead votes cast count; anyone after that gets Max votes reached. Counted: " +
                    dv.counted.length +
                    " of 3" +
                    (dv.dropped.length ? "; not counted (final vote kept): " + dv.dropped.map((id: string) => nameOfFrom(state, id)).join(", ") : "") +
                    "."
                  );
                })()}
                <PendingTag />
              </div>
              {tally.map((t: { id: string; name: string; votes: number }) => (
                <div key={t.id} style={{ marginBottom: 4 }}>
                  {t.name}: {t.votes}
                </div>
              ))}
              <div style={{ ...wrap, marginTop: 10 }}>
                {tally.map((t: { id: string; name: string; votes: number }) =>
                  t.id === NO_EXEC ? (
                    <button
                      key={t.id}
                      type="button"
                      style={btnStyle("quiet")}
                      onClick={() => props.setState((st: GameState) => closeDawnAccord({ ...st, hadExecution: false }))}
                    >
                      Close with no execution
                    </button>
                  ) : (
                    <button
                      key={t.id}
                      type="button"
                      style={btnStyle("ember")}
                      onClick={() =>
                        props.setState((st: GameState) => {
                          const voters = Object.keys(st.votes).filter((vid: string) => st.votes[vid] === t.id);
                          return executeNominee(st, t.id);
                        })
                      }
                    >
                      Execute {t.name}
                    </button>
                  ),
                )}
              </div>
            </div>
          ) : null}
        </SectionCard>
      ) : null}

      {state.dealt && state.players.some((p: Player) => p.roleId === "the-ashen-mind") ? (
        <SectionCard title="Ashen Mind disguises" note="The app suggests a false Lumen role for each masked living player. Override before or during the round. In the finished app you would confirm these before the Mind sees the snapshot.">
          {living.filter((p: Player) => roleOf(p.roleId).masked).map((p: Player) => (
            <label key={p.id} style={{ display: "block", marginBottom: 8 }}>
              <span style={labelStyle()}>{p.name} (true: {roleOf(p.roleId).name})</span>
              <select
                style={inputStyle()}
                value={state.mindMasks[p.id] || ""}
                onChange={(e: ChangeEvent<HTMLSelectElement>) =>
                  props.setState((s: GameState) => ({ ...s, mindMasks: { ...s.mindMasks, [p.id]: e.target.value } }))
                }
              >
                <option value="">—</option>
                {lumenRolePool().map((r: RoleDef) => (
                  <option key={r.id} value={r.id}>
                    {r.name}
                  </option>
                ))}
              </select>
            </label>
          ))}
        </SectionCard>
      ) : null}

      {state.dealt && cutoffApplies(state)
        ? (() => {
            const ci = cutoffInfo(state);
            const holder = cutoffKillHolder(state);
            return (
              <SectionCard title="Test rule ON: 75% succession cutoff" note="Playtest variant (Caden, Nov 18 card), not a core rule. Checked only after The Ashen Tyrant is dead.">
                <div style={{ fontSize: 14, color: C.text, lineHeight: 1.6 }}>
                  Starting Lumen: {ci.start}. Cutoff: {ci.threshold} or fewer living Lumen. Living Lumen now: {ci.living}.{" "}
                  {!state.tyrantHasDied
                    ? "The Tyrant is alive, so the cutoff is not checked yet."
                    : state.shadowTakeover
                      ? "The Shadow Blade holds the kill, so the cutoff does not apply."
                      : holder
                        ? "Kill holder: " + holder.name + ". " + (ci.reached ? "Cutoff reached." : (ci.living - ci.threshold) + " more Lumen death(s) end the game as a Lumen win.")
                        : "No Ashen successor."}
                </div>
              </SectionCard>
            );
          })()
        : null}

      {state.dealt ? (
        <SectionCard
          title="Ash Touched info"
          note="Caden (Nov 17): any information the Ash Touched player receives may be true or false. Each result is false with the chance below unless you force it for that round. Mire Touched results stay false. Caden (Nov 18): “It can go either way. Balance the game with it. If the ashen are losing bad help them with some false information.” Witness and Ashen Mind results arrive at the start of a round, so set those under that round."
        >
          <div style={{ ...wrap, marginBottom: 10 }}>
            <label style={{ flex: "1 1 220px" }}>
              <span style={labelStyle()}>Chance of a false result (%)</span>
              <input
                style={inputStyle()}
                type="number"
                min={0}
                max={100}
                value={clampPct(state.atFalsePct)}
                onChange={(e: ChangeEvent<HTMLInputElement>) =>
                  props.setState((st: GameState) => ({ ...st, atFalsePct: clampPct(Number(e.target.value)) }))
                }
              />
            </label>
          </div>
          {(() => {
            const st = ashenStanding(state);
            return (
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 10 }}>
                Balance lever: raise the chance (or force false) to give more false information when the Ashen are losing badly; lower it when they are
                running away with the game. The app never changes it by itself.{" "}
                <span style={{ color: st.behind ? C.gold : C.muted }}>
                  Living now: {st.livingAshen} Ashen vs {st.livingOthers} others{st.behind ? " — Ashen are behind (rough guide)" : ""}.
                </span>
              </div>
            );
          })()}
          {state.players.filter((p: Player) => p.ashTouched && p.alive).length === 0 ? (
            <div style={{ color: C.muted, fontSize: 14 }}>No living player is marked Ash Touched.</div>
          ) : null}
          {state.players
            .filter((p: Player) => p.ashTouched && p.alive)
            .map((p: Player) => (
              <div key={p.id} style={{ marginBottom: 10 }}>
                {[state.round, state.round + 1].map((rd: number) => {
                  const cur = (state.atOverrides || {})[atOverrideKey(rd, p.id)] || "";
                  return (
                    <div key={rd} style={{ ...wrap, alignItems: "center", marginBottom: 6 }}>
                      <span style={{ fontSize: 14, minWidth: 220 }}>
                        {p.name} ({roleOf(p.roleId).name}) · round {rd}
                        {rd === state.round ? " (now)" : " (next)"}
                      </span>
                      {[
                        { v: "", t: "Use the chance" },
                        { v: "true", t: "Force true" },
                        { v: "false", t: "Force false" },
                      ].map((o: { v: string; t: string }) => (
                        <button
                          key={o.v}
                          type="button"
                          style={btnStyle(cur === o.v ? "gold" : "quiet")}
                          onClick={() => props.setState((st: GameState) => setAtOverride(st, p.id, rd, o.v))}
                        >
                          {o.t}
                        </button>
                      ))}
                    </div>
                  );
                })}
              </div>
            ))}
          {(state.atRolls || []).length > 0 ? (
            <div style={{ marginTop: 6 }}>
              <div style={labelStyle()}>Ash Touched results so far (GM only)</div>
              {(state.atRolls || []).slice(0, 12).map((r: AtRoll) => (
                <div key={r.id} style={{ fontSize: 13, color: C.muted }}>
                  Round {r.round} · {nameOfFrom(state, r.playerId)} · {r.label}: {r.lie ? "FALSE" : "TRUE"} ({r.how})
                </div>
              ))}
            </div>
          ) : null}
        </SectionCard>
      ) : null}

      {state.summonedIds.length === 2 ? (
        <SectionCard title="Summon chat" note="The GM can watch. The Necroreclaimer may ask yes-or-no questions only. Each summoned player's first answer is binding in the rules.">
          <ChatPane
            fontFamily=""
            messages={state.chats.filter((m: ChatMsg) => m.channel === summonChannel(state.round))}
            draft={props.drafts[summonChannel(state.round)] || ""}
            onDraft={(v: string) => props.setDraft(summonChannel(state.round), v)}
            onSend={() => props.sendChat(summonChannel(state.round), "gm")}
            placeholder="Watch or write as the GM…"
            nameOf={props.nameOf}
          />
        </SectionCard>
      ) : null}

      <SectionCard title="Game log">
        <div style={{ maxHeight: 360, overflowY: "auto" }}>
          {state.log.map((item: LogItem) => (
            <div key={item.id} style={{ fontSize: 13, lineHeight: 1.45, marginBottom: 8, color: C.text, borderBottom: "1px solid " + C.border, paddingBottom: 8 }}>
              {item.text}
            </div>
          ))}
        </div>
      </SectionCard>
    </div>
  );
}

function modifierSummary(p: Player): string {
  const bits: string[] = [];
  if (p.ashTouched) bits.push("Ash Touched");
  if (p.mireTouched) bits.push("Mire Touched");
  if (p.poisonCount > 0) bits.push("Poison " + p.poisonCount + "/3");
  if (p.shielded) bits.push("Shielded");
  if (p.soulboundWith !== "") bits.push("Soulbound");
  if (p.failsafeCancelled) bits.push("Failsafe");
  if (p.tempRoleId !== "") bits.push("Swap → " + roleOf(p.tempRoleId).name);
  if (p.syndicateMember) bits.push("Syndicate");
  if (p.voteSilenced) bits.push("Silenced");
  if (roleOf(p.roleId).charged) bits.push("Charges " + p.charges);
  return bits.length ? bits.join(" · ") : "—";
}

function ModifierForm(props: {
  player: Player;
  players: Player[];
  patchPlayer: (id: string, fn: (p: Player) => Player) => void;
}): ReactNode {
  const p = props.player;
  const toggle = (key: "ashTouched" | "mireTouched" | "shielded" | "failsafeCancelled" | "syndicateMember" | "voteSilenced") => {
    props.patchPlayer(p.id, (x: Player) => ({ ...x, [key]: !x[key] }));
  };
  return (
    <div>
      <div style={wrap}>
        <button
          type="button"
          style={btnStyle(p.ashTouched ? "gold" : "quiet")}
          onClick={() => {
            // Caden: exactly 1 Ash Touched per game. Turning it on here clears it from everyone else.
            const on = !p.ashTouched;
            for (const q of props.players) {
              if (q.id === p.id) props.patchPlayer(q.id, (x: Player) => ({ ...x, ashTouched: on }));
              else if (on && q.ashTouched) props.patchPlayer(q.id, (x: Player) => ({ ...x, ashTouched: false }));
            }
          }}
        >
          Ash Touched{p.ashTouched ? " (on — the 1 per game)" : ""}
        </button>
        <button type="button" style={btnStyle(p.mireTouched ? "gold" : "quiet")} onClick={() => toggle("mireTouched")}>
          Mire Touched{p.mireTouched ? " (on)" : ""}
        </button>
        <button type="button" style={btnStyle(p.shielded ? "gold" : "quiet")} onClick={() => toggle("shielded")}>
          Shielded{p.shielded ? " (on)" : ""}
        </button>
        <button type="button" style={btnStyle(p.failsafeCancelled ? "ember" : "quiet")} onClick={() => toggle("failsafeCancelled")}>
          Failsafe-cancelled{p.failsafeCancelled ? " (on)" : ""}
        </button>
        <button type="button" style={btnStyle(p.syndicateMember ? "gold" : "quiet")} onClick={() => toggle("syndicateMember")}>
          Syndicate member{p.syndicateMember ? " (on)" : ""}
        </button>
        <button type="button" style={btnStyle(p.voteSilenced ? "ember" : "quiet")} onClick={() => toggle("voteSilenced")}>
          Vote silenced{p.voteSilenced ? " (on)" : ""}
        </button>
      </div>
      <div style={{ ...wrap, marginTop: 10 }}>
        <label style={{ flex: "1 1 140px" }}>
          <span style={labelStyle()}>Poison count</span>
          <select
            style={inputStyle()}
            value={String(p.poisonCount)}
            onChange={(e: ChangeEvent<HTMLSelectElement>) => {
              const n = parseInt(e.target.value, 10);
              props.patchPlayer(p.id, (x: Player) => ({ ...x, poisonCount: n }));
            }}
          >
            <option value="0">0</option>
            <option value="1">1</option>
            <option value="2">2</option>
            <option value="3">3</option>
          </select>
        </label>
        <label style={{ flex: "1 1 180px" }}>
          <span style={labelStyle()}>Soulbound pair (Caden: GM places it, anyone can be Soulbound, if one dies both die. players are never told; Nov 17 card. Required at 10+ players, Nov 18)</span>
          <select
            style={inputStyle()}
            value={p.soulboundWith}
            onChange={(e: ChangeEvent<HTMLSelectElement>) => {
              const other = e.target.value;
              props.patchPlayer(p.id, (x: Player) => ({ ...x, soulboundWith: other }));
              if (other !== "") props.patchPlayer(other, (x: Player) => ({ ...x, soulboundWith: p.id }));
              for (const q of props.players) {
                if (q.soulboundWith === p.id && q.id !== other) {
                  props.patchPlayer(q.id, (x: Player) => ({ ...x, soulboundWith: x.id === other ? p.id : "" }));
                }
              }
            }}
          >
            <option value="">None</option>
            {props.players
              .filter((x: Player) => x.id !== p.id)
              .map((x: Player) => (
                <option key={x.id} value={x.id}>
                  {x.name}
                </option>
              ))}
          </select>
        </label>
        <label style={{ flex: "1 1 180px" }}>
          <span style={labelStyle()}>Temporary swapped role</span>
          <select
            style={inputStyle()}
            value={p.tempRoleId}
            onChange={(e: ChangeEvent<HTMLSelectElement>) => props.patchPlayer(p.id, (x: Player) => ({ ...x, tempRoleId: e.target.value }))}
          >
            <option value="">None (real role)</option>
            {ROLES.map((r: RoleDef) => (
              <option key={r.id} value={r.id}>
                {r.name}
              </option>
            ))}
          </select>
        </label>
      </div>
    </div>
  );
}

function SelfKnownAnswer(props: { state: GameState; setState: (fn: (prev: GameState) => GameState) => void }): ReactNode {
  const q = props.state.actions.filter((a: ActionSub) => a.round === props.state.round && a.label.indexOf("Self Known") >= 0);
  const last = q[q.length - 1];
  if (!last || last.targets[0] === undefined) return null;
  const target = playerById(props.state.players, last.targets[0]);
  if (!target) return null;
  const asked = last.extra;
  // Bug fix (Nov 17): role names have spaces, so take the role name after "Is <target name> " (the old regex split
  // "Is Tor The Ashen Tyrant?" as "Tor The Ashen" + "Tyrant", which made every true answer "No").
  const prefix = "Is " + target.name + " ";
  const roleName = last.extra.indexOf(prefix) === 0 && last.extra.slice(-1) === "?" ? last.extra.slice(prefix.length, -1) : "";
  const actual = roleOf(target.roleId).name === roleName;
  const asker = playerById(props.state.players, last.playerId);
  // Caden (Nov 17): an Ash Touched asker's answer may be true or false. It is decided when you send it
  // (the GM's chance, or the per-round override in the Ash Touched info card). Mire Touched: always false.
  const atPending = Boolean(asker && asker.ashTouched && !asker.mireTouched);
  const ov = asker ? (props.state.atOverrides || {})[atOverrideKey(props.state.round, asker.id)] : undefined;
  const yes = asker ? flipYesNo(actual, asker.mireTouched || (atPending && ov === "false")) : actual;
  const undecided = atPending && ov !== "true" && ov !== "false";
  return (
    <div style={{ marginTop: 12 }}>
      <div style={labelStyle()}>Self Known question this round</div>
      <div style={{ fontSize: 14, marginBottom: 8 }}>{asked}</div>
      {atPending ? (
        <div style={{ color: C.muted, fontSize: 13, marginBottom: 8 }}>
          {asker ? asker.name : ""} is Ash Touched (Caden: the answer may be true or false).{" "}
          {undecided ? "It will be false with a " + clampPct(props.state.atFalsePct) + "% chance when you send it." : "GM override for this round: " + (ov === "true" ? "true" : "false") + "."}
        </div>
      ) : null}
      <button
        type="button"
        style={btnStyle("gold")}
        onClick={() =>
          props.setState((s: GameState) => {
            if (!asker) return s;
            const r = atPending ? infoLies(s, asker, "Self Known question") : { lie: asker.mireTouched, state: s };
            const y = flipYesNo(actual, r.lie);
            return addResult(addLog(r.state, "GM answered The Self Known: " + (y ? "Yes" : "No") + "."), asker.id, asked + " — " + (y ? "Yes" : "No") + ".");
          })
        }
      >
        {undecided ? "Send answer (rolled)" : "Send answer (" + (yes ? "Yes" : "No") + ")"}
      </button>
    </div>
  );
}
